func (h *Handlers) CreateClaim(c echo.Context, params serverhttp.CreateClaimParams) error {
	var request serverhttp.RequestCreateClaim

	if err := c.Bind(&request); err != nil {
		err = c.JSON(http.StatusBadRequest, serverhttp.ResponseBadRequest{
			Code:    serverhttp.INVALIDSCHEMA,
			Details: helpers.Ptr([]string{err.Error()}),
		})
		if err != nil {
			return fmt.Errorf("ctx.JSON: %w", err)
		}

		return nil
	}

	if err := validate.V().StructCtx(c.Request().Context(), request); err != nil {
		err = c.JSON(http.StatusBadRequest, serverhttp.ResponseBadRequest{
			Code:    serverhttp.INVALIDSCHEMA,
			Details: helpers.Ptr([]string{err.Error()}),
		})
		if err != nil {
			return fmt.Errorf("ctx.JSON: %w", err)
		}

		return nil
	}

	createClaimParams, err := dto.ToDTOCreateClaimParams(&request)
	if err != nil {
		return c.JSON(http.StatusInternalServerError, nil) //nolint:wrapcheck
	}

	claimID, err := h.S.ClaimService.CreateClaim(c.Request().Context(), params.XUserID, createClaimParams)

	//nolint:wrapcheck
	switch {
	case err == nil:
		return c.JSON(http.StatusCreated, serverhttp.ResponseCreateClaim{
			ClaimId: claimID,
		})

	case errors.Is(err, infra.ErrBadRequest):
		return c.JSON(http.StatusBadRequest, &serverhttp.ResponseBadRequest{
			Code:    serverhttp.OTHERVALIDATIONERRORS,
			Details: helpers.Ptr([]string{err.Error()}),
		})

	default:
		return c.JSON(http.StatusInternalServerError, nil)
	}
}

