func ToDTOCreateClaimParams(
	params *serverhttp.RequestCreateClaim,
) (*CreateClaimParams, error) {
	b, err := json.Marshal(params.Meta)
	if err != nil {
		return nil, fmt.Errorf("json.Marshal: %w", err)
	}

	var needDropOffCode bool
	if params.NeedDropOffCode != nil {
		needDropOffCode = *params.NeedDropOffCode
	}

	var needReturn bool
	if params.NeedReturn != nil {
		needReturn = *params.NeedReturn
	}

	var isBagRequired bool
	if params.IsBagRequired != nil {
		isBagRequired = *params.IsBagRequired
	}

	return &CreateClaimParams{
		Tariff:          Tariff(params.Tariff),
		DueTime:         params.DueTime,
		Comment:         params.Comment,
		RoutePoints:     toDTORoutePoints(params.RoutePoints),
		Items:           toDTOItems(params.Items),
		NeedDropOffCode: needDropOffCode,
		NeedReturn:      needReturn,
		IsBagRequired:   isBagRequired,
		Meta:            b,
		Email:           params.Email,
	}, nil
}

func toDTORoutePoints(
	httpRoutePoints []serverhttp.RoutePoint,
) []RoutePoint {
	var ret []RoutePoint //nolint:prealloc

	for _, p := range httpRoutePoints {
		ret = append(ret, RoutePoint{
			Address: &Address{
				Comment: p.Address.Comment,
				Coordinates: &Coordinates{
					Lat: p.Address.Coordinates.Lat,
					Lon: p.Address.Coordinates.Lon,
				},
				DoorCode: p.Address.DoorCode,
				Flat:     p.Address.Flat,
				Floor:    p.Address.Floor,
				FullName: p.Address.FullName,
				Porch:    p.Address.Porch,
			},
			Contact: &Contact{
				ExtensionNumber: p.Contact.ExtensionNumber,
				ExtraPhone:      p.Contact.ExtraPhone,
				Name:            p.Contact.Name,
				Phone:           p.Contact.Phone,
			},
			Type: RoutePointType(p.PointType),
		})
	}

	return ret
}

func toDTOItems(items serverhttp.Items) Items {
	ret := Items{
		Cost:      items.Cost,
		ItemsInfo: nil,
		Weight:    items.Weight,
	}

	if items.ItemsInfo == nil {
		return ret
	}

	var itemsInfo []ItemInfo //nolint:prealloc

	for _, ii := range *items.ItemsInfo {
		itemsInfo = append(itemsInfo, ItemInfo{
			Depth:  ii.Depth,
			Height: ii.Height,
			Name:   ii.Name,
			Price:  ii.Price,
			Width:  ii.Width,
		})
	}

	ret.ItemsInfo = itemsInfo

	return ret
}

func (s Service) CreateClaim(
	ctx context.Context,
	userID string,
	params *dto.CreateClaimParams,
) (uuid.UUID, error) {
	ctx, span := tracing.Start(ctx, "claim:CreateClaim")
	defer span.End()

	externalOrderId, err := s.externalOrderIDGen()
	if err != nil {
		return uuid.UUID{}, fmt.Errorf("helpers.GenerateExternalOrderId: %w", err)
	}

	metaMap := map[string]any{
		"user_id": userID,
	}

	meta, err := json.Marshal(metaMap)
	if err != nil {
		return uuid.UUID{}, fmt.Errorf("failed to marshal meta: %w", err)
	}

	params.Meta = meta

	srcPoint := params.RoutePoints[0]
	if params.RoutePoints[1].Type == dto.RouteTypeSource {
		srcPoint = params.RoutePoints[1]
	}

	srcPoint.Address.Comment = makeComment(params)
	srcPoint.Address.FullName = srcPoint.Address.FullAddress()

	dynConfig, err := configurator.Get[features.Features]()
	if err != nil {
		return uuid.Nil, fmt.Errorf("configurator.Get[features]: %w", err)
	}
	// Если для новых пользователей включена скидка
	if dynConfig.NewUserDiscountEnabled {
		claimsCount, err := s.repo.GetClaimsCountByUser(ctx, userID)
		if err != nil {
			return uuid.Nil, fmt.Errorf("s.repo.GetClaimsCountByUser: %w", err)
		}

		// Используем тариф "new-user" для пользователей с определенным количеством завершенных заказов (см.конфигуратор)
		if claimsCount <= dynConfig.NewUserOrderThreshold {
			switch params.Tariff {
			case dto.TariffQuick, dto.TariffQuickNewUser:
				params.Tariff = dto.TariffQuickNewUser
			case dto.TariffFourHours, dto.TariffFourHoursNewUser:
				params.Tariff = dto.TariffFourHoursNewUser
			}
		}
	}

	claimID, err := s.lastmileomsClient.CreateClaim(ctx, externalOrderId, params)
	if err != nil {
		s.logger.Error("failed to create claim in last mile OMS", zap.Error(err))

		switch {
		case errors.Is(err, http.ErrBadRequest):
			return uuid.Nil, fmt.Errorf("%w: %w", service.ErrBadRequest, err)
		default:
			return uuid.Nil, fmt.Errorf("lmClient.CreateClaim: %w", err)
		}
	}

	createClaimParams := &dto.CreateDBClaimParams{
		ClaimID:         claimID,
		UserID:          userID,
		ExternalOrderID: externalOrderId,
		Tariff:          params.Tariff,
		Email:           params.Email,
	}

	if _, err := s.repo.Create(ctx, createClaimParams); err != nil {
		s.logger.Error("failed to create claim in database", zap.Error(err))

		return uuid.Nil, fmt.Errorf("failed to save claim: %w", err)
	}

	s.logger.Info(
		"claim created",
		zap.String("claim_id", claimID.String()),
		zap.String("external_order_id", externalOrderId),
	)

	return claimID, nil
}

