func GenerateExternalOrderId() (string, error) {
	sID, err := generateSnowflakeID()
	if err != nil {
		return "", err
	}

	externalOrderId := fmt.Sprintf("%s-%010d", config.OrderIDPrefix, sID)

	return externalOrderId, nil
}

func generateSnowflakeID() (int64, error) {
	node, err := snowflake.NewNode(1)
	if err != nil {
		return 0, fmt.Errorf("failed to create a new Snowflake node: %w", err)
	}

	return node.Generate().Int64() % maxOrderId, nil
}

func makeComment(params *dto.CreateClaimParams) *string {
	srcPoint := params.RoutePoints[0]
	if params.RoutePoints[1].Type == dto.RouteTypeSource {
		srcPoint = params.RoutePoints[1]
	}

	comment := commentTemplate

	if srcPoint.Contact.Name != nil {
		comment += fmt.Sprintf("%s, ", *srcPoint.Contact.Name)
	}

	comment += srcPoint.Contact.Phone
	if srcPoint.Address.Comment != nil {
		comment += fmt.Sprintf("\n%s", *srcPoint.Address.Comment)
	}

	return &comment
}

func (a *Address) FullAddress() string {
	var builder strings.Builder

	builder.WriteString(a.FullName)

	if a.Porch != nil && *a.Porch != "" {
		builder.WriteString(fmt.Sprintf(", подъезд %s", *a.Porch))
	}

	if a.Floor != nil && *a.Floor != "" {
		builder.WriteString(fmt.Sprintf(", этаж %s", *a.Floor))
	}

	if a.Flat != nil && *a.Flat != "" {
		builder.WriteString(fmt.Sprintf(", кв. %s", *a.Flat))
	}

	if a.DoorCode != nil && *a.DoorCode != "" {
		builder.WriteString(fmt.Sprintf(", код домофона %s", *a.DoorCode))
	}

	return builder.String()
}

