func (c *Client) CreateClaim(
	ctx context.Context,
	externalOrderID string,
	params *dto.CreateClaimParams,
) (uuid.UUID, error) {
	ctx, span := tracing.Start(ctx, "lastmileoms:CreateClaim")
	defer span.End()

	reqId := uuid.New()

	httpParams := toHTTPCreateClaimParams(externalOrderID, params)

	partnerID := c.PartnerIDForTariff(params.Tariff)

	log := c.logger.With(
		zap.String("http_client", "lm_oms"),
		zap.String("method", "accept_claim"),
		zap.String("request_id", reqId.String()),
		zap.String("partner_id", partnerID),
		zap.Any("params", params),
	)

	resp, err := c.client.CreateClaimWithResponse(
		ctx,
		&lmHTTP.CreateClaimParams{
			XPartnerID: partnerID,
			RequestId:  reqId.String(),
		},
		httpParams,
	)
	if err != nil {
		return uuid.Nil, fmt.Errorf("c.client.CreateClaim: %w", err)
	}

	switch resp.StatusCode() {
	case http.StatusOK:
		return resp.JSON200.ClaimId, nil

	case http.StatusBadRequest:
		log.Error(
			"response code 400",
			zap.Any("details", helpers.Deref(resp.JSON400.Details)),
		)

		return uuid.Nil, infra.ErrBadRequest

	default:
		log.Error(
			"unhandled status code",
			zap.Int("status_code", resp.StatusCode()),
		)

		return uuid.Nil, fmt.Errorf("unhandled status code: %d", resp.StatusCode())
	}
}

