func toHTTPRoutePoints(routePoints []dto.RoutePoint) []lastmileomshttpclient.RoutePoint {
	var ret []lastmileomshttpclient.RoutePoint //nolint:prealloc

	for _, p := range routePoints {
		contact := lastmileomshttpclient.Contact{
			ExtensionNumber: nil,
			ExtraPhone:      nil,
			Name:            nil,
			Phone:           "+79999999999", // fake phone для того, чтобы не править контракт в омс пока
		}

		if p.Contact != nil {
			contact.ExtensionNumber = p.Contact.ExtensionNumber
			contact.ExtraPhone = p.Contact.ExtraPhone
			contact.Name = p.Contact.Name
			contact.Phone = p.Contact.Phone
		}

		ret = append(ret, lastmileomshttpclient.RoutePoint{
			Address: lastmileomshttpclient.Address{
				Comment: p.Address.Comment,
				Coordinates: lastmileomshttpclient.Coordinates{
					Lat: p.Address.Coordinates.Lat,
					Lon: p.Address.Coordinates.Lon,
				},
				DoorCode: p.Address.DoorCode,
				Flat:     p.Address.Flat,
				Floor:    p.Address.Floor,
				FullName: p.Address.FullName,
				Porch:    p.Address.Porch,
			},
			Contact:      contact,
			PointType:    lastmileomshttpclient.RoutePointType(p.Type),
			TransferCode: nil,
		})
	}

	return ret
}

func (c *ClientWithResponses) CreateClaimWithResponse(ctx context.Context, params *CreateClaimParams, body CreateClaimJSONRequestBody, reqEditors ...RequestEditorFn) (*CreateClaimResponse, error) {
