func (r *Repository) Create(ctx context.Context, params *dto.CreateDBClaimParams) (*claim.Claim, error) {
	ctx, span := tracing.Start(ctx, "database:CreateClaim")
	defer span.End()

	span.SetAttributes(
		attribute.Stringer("claim_id", params.ClaimID),
	)

	initState := claim.State{
		Status:       claim.StatusCreated,
		CancelReason: nil,
	}

	b, err := json.Marshal(initState)
	if err != nil {
		return nil, fmt.Errorf("json.Marshal: %w", err)
	}

	c, err := r.master.CreateClaim(ctx, queries.CreateClaimParams{
		ClaimID:         params.ClaimID,
		UserID:          params.UserID,
		State:           b,
		ExternalOrderID: params.ExternalOrderID,
		Tariff:          queries.TariffEnum(params.Tariff),
		Email:           params.Email,
	})
	if err != nil {
		return nil, fmt.Errorf("r.master.CreateClaim: %w", err)
	}

	return &claim.Claim{
		ClaimID:         c.ClaimID,
		ExternalOrderID: c.ExternalOrderID,
		Tariff:          claim.Tariff(c.Tariff),
		Email:           c.Email,
		UserID:          c.UserID,
		Payment:         nil,
		State:           initState,
		CreatedAt:       c.CreatedAt.Time,
		UpdatedAt:       c.UpdatedAt.Time,
		DeletedAt:       nil,
	}, nil
}

