func ToDTOEstimateClaimParams(
	params *serverhttp.RequestEstimateClaim,
) *EstimateClaimParams {
	return &EstimateClaimParams{
		RoutePoints: toDTORoutePointsNoContacts(params.RoutePoints),
		Items:       toDTOItems(params.Items),
		Tariff:      Tariff(params.Tariff),
	}
}

func toDTORoutePointsNoContacts(
	httpRoutePoints []serverhttp.RoutePointNoContact,
) []RoutePoint {
	var ret []RoutePoint //nolint:prealloc

	for _, p := range httpRoutePoints {
		var contact *Contact
		if p.Contact != nil {
			contact = &Contact{
				ExtensionNumber: p.Contact.ExtensionNumber,
				ExtraPhone:      p.Contact.ExtraPhone,
				Name:            p.Contact.Name,
				Phone:           p.Contact.Phone,
			}
		}

		ret = append(ret, RoutePoint{
			Address: &Address{
				Comment: p.Address.Comment,
				Coordinates: &Coordinates{
					Lat: p.Address.Coordinates.Lat,
					Lon: p.Address.Coordinates.Lon,
				},
				DoorCode: p.Address.DoorCode,
				Flat:     p.Address.Flat,
				Floor:    p.Address.Floor,
				FullName: p.Address.FullName,
				Porch:    p.Address.Porch,
			},
			Type:    RoutePointType(p.PointType),
			Contact: contact,
		})
	}

	return ret
}

func toDTOItems(items serverhttp.Items) Items {
	ret := Items{
		Cost:      items.Cost,
		ItemsInfo: nil,
		Weight:    items.Weight,
	}

	if items.ItemsInfo == nil {
		return ret
	}

	var itemsInfo []ItemInfo //nolint:prealloc

	for _, ii := range *items.ItemsInfo {
		itemsInfo = append(itemsInfo, ItemInfo{
			Depth:  ii.Depth,
			Height: ii.Height,
			Name:   ii.Name,
			Price:  ii.Price,
			Width:  ii.Width,
		})
	}

	ret.ItemsInfo = itemsInfo

	return ret
}

func (s *Service) EstimateClaim(
	ctx context.Context,
	params *dto.EstimateClaimParams,
) (*dto.Estimation, error) {
	ctx, span := tracing.Start(ctx, "claim:EstimateClaim")
	defer span.End()

	srcPoint := params.RoutePoints[0]
	if params.RoutePoints[1].Type == dto.RouteTypeSource {
		srcPoint = params.RoutePoints[1]
	}

	var phone *string
	if srcPoint.Contact != nil {
		phone = &srcPoint.Contact.Phone
	}

	s.logger.Info("estimating claim", zap.Any("phone", phone))

	estimation, err := s.lastmileomsClient.EstimateClaim(ctx, params)
	if err != nil {
		return nil, fmt.Errorf("s.lastmileomsClient.EstimateClaim: %w", err)
	}

	return estimation, nil
}

