func toHTTPRoutePoints(routePoints []dto.RoutePoint) []lastmileomshttpclient.RoutePoint {
	var ret []lastmileomshttpclient.RoutePoint //nolint:prealloc

	for _, p := range routePoints {
		contact := lastmileomshttpclient.Contact{
