func toDtoItems(lmItems lastmileomshttpclient.Items) dto.Items {
	items := dto.Items{
		Cost:      lmItems.Cost,
		Weight:    lmItems.Weight,
		ItemsInfo: nil,
	}

	if lmItems.ItemsInfo != nil {
		itemsInfo := make([]dto.ItemInfo, 0, len(*lmItems.ItemsInfo))

		for _, itemInfo := range *lmItems.ItemsInfo {
			itemsInfo = append(itemsInfo, dto.ItemInfo{
				Depth:  itemInfo.Depth,
				Height: itemInfo.Height,
				Width:  itemInfo.Width,
				Name:   itemInfo.Name,
				Price:  itemInfo.Price,
			})
		}

		items.ItemsInfo = itemsInfo
	}

	return items
}

func toDtoRoutePoints(lmRoutePoints []lastmileomshttpclient.RoutePoint) []dto.RoutePoint {
	routePoints := make([]dto.RoutePoint, len(lmRoutePoints))

	for i, rp := range lmRoutePoints {
		routePoints[i] = dto.RoutePoint{
			Address: &dto.Address{
				Comment: rp.Address.Comment,
				Coordinates: &dto.Coordinates{
					Lat: rp.Address.Coordinates.Lat,
					Lon: rp.Address.Coordinates.Lon,
				},
				DoorCode: rp.Address.DoorCode,
				Flat:     rp.Address.Flat,
