func (h *Handlers) CancelClaim(c echo.Context, claimID serverhttp.ClaimID, params serverhttp.CancelClaimParams) error {
	var request serverhttp.RequestCancelClaim

	if err := c.Bind(&request); err != nil {
		err = c.JSON(http.StatusBadRequest, serverhttp.ResponseBadRequest{
			Code:    serverhttp.INVALIDSCHEMA,
			Details: helpers.Ptr([]string{err.Error()}),
		})
		if err != nil {
			return fmt.Errorf("ctx.JSON: %w", err)
		}

		return nil
	}

	if err := validate.V().StructCtx(c.Request().Context(), request); err != nil {
		err = c.JSON(http.StatusBadRequest, serverhttp.ResponseBadRequest{
			Code:    serverhttp.INVALIDSCHEMA,
			Details: helpers.Ptr([]string{err.Error()}),
		})
		if err != nil {
			return fmt.Errorf("ctx.JSON: %w", err)
		}

		return nil
	}

	var cancelReason *dto.CancelByPartnerReason
	if request.CancelReason != nil {
		cancelReason = &dto.CancelByPartnerReason{
			Code:    dto.CancelByPartnerReasonCode(request.CancelReason.Code),
			Message: request.CancelReason.Message,
		}
	}

	err := h.S.ClaimService.CancelUserClaim(
		c.Request().Context(),
		&dto.CancelUserClaimParams{
			ClaimId:      claimID,
			UserId:       params.XUserID,
			CancelReason: cancelReason,
		},
	)

	switch {
	case errors.Is(err, nil):
		err = c.JSON(http.StatusOK, &serverhttp.ResponseCancelClaim{
			ClaimId: claimID,
		})
		if err != nil {
			return fmt.Errorf("ctx.JSON: %w", err)
		}

		return nil
	case errors.Is(err, infra.ErrBadRequest):
		err = c.JSON(http.StatusBadRequest, &serverhttp.ResponseBadRequest{
			Code:    serverhttp.OTHERVALIDATIONERRORS,
			Details: helpers.Ptr([]string{err.Error()}),
		})
		if err != nil {
			return fmt.Errorf("ctx.JSON: %w", err)
		}

		return nil

	case errors.Is(err, service.ErrClaimNotFound):
		err = c.JSON(http.StatusNotFound, &serverhttp.ResponseNotFound{
			Code:    serverhttp.NOTFOUND,
			Details: helpers.Ptr([]string{"claim not found"}),
		})
		if err != nil {
			return fmt.Errorf("ctx.JSON: %w", err)
		}

		return nil
	default:
		err = c.JSON(http.StatusInternalServerError, nil)
		if err != nil {
			return fmt.Errorf("ctx.JSON: %w", err)
		}
	}

	return nil
}

