func (c *Client) ClaimInfo(ctx context.Context, claimID uuid.UUID, partnerID string) (dto.Claim, error) {
	// TODO: подумать над переходом на ручку ClaimsList, где партнер не обязательный
	ctx, span := tracing.Start(ctx, "lastmileoms:ClaimInfo")
	defer span.End()

	span.SetAttributes(
		attribute.Stringer("claim_id", claimID),
	)

	log := c.logger.With(
		zap.String("http_client", "lm_oms"),
		zap.String("method", "claims_info"),
		zap.String("claim_id", claimID.String()),
	)

	req := lastmileomshttpclient.RequestClaimsInfo{
		ClaimIds: []uuid.UUID{
			claimID,
		},
	}

	resp, err := c.client.ClaimsInfoWithResponse(ctx, &lastmileomshttpclient.ClaimsInfoParams{
		Expand: &[]string{
			string(lastmileomshttpclient.ClaimsInfoParamsExpandBillingDetails),
			string(lastmileomshttpclient.ClaimsInfoParamsExpandPartnerId),
			string(lastmileomshttpclient.ClaimsInfoParamsExpandDropOffCode),
		},
		XPartnerID: partnerID,
	}, req)
	if err != nil {
		return dto.Claim{}, fmt.Errorf("c.client.ClaimsInfoWithResponse: %w", err)
	}

	switch resp.StatusCode() {
	case http.StatusOK:
		claims, err := toDtoClaims(resp.JSON200.Claims, c.tariffQuickPartnerID, c.tariffFourHoursPartnerID)
		if err != nil {
			return dto.Claim{}, fmt.Errorf("toDtoClaims: %w", err)
		}

		return claims[0], nil

	case http.StatusBadRequest:
		log.Error(
			"response code 400",
			zap.Any("details", helpers.Deref(resp.JSON400.Details)),
		)

		return dto.Claim{}, errors.Join(infra.ErrBadRequest, fmt.Errorf("%s", helpers.Deref(resp.JSON400.Details)))

	default:
		log.Error(
			"unhandled status code",
