func (h *Handlers) PayClaim(ctx echo.Context, claimID serverhttp.ClaimID, params serverhttp.PayClaimParams) error {
	var req serverhttp.RequestPayClaim

	if err := ctx.Bind(&req); err != nil {
		//nolint:wrapcheck
		return ctx.JSON(http.StatusBadRequest, serverhttp.ResponseError{
			Code:    serverhttp.INVALIDSCHEMA,
			Details: helpers.Ptr([]string{err.Error()}),
		})
	}

	err := validate.V().StructCtx(ctx.Request().Context(), req)
	if err != nil {
		err = ctx.JSON(http.StatusBadRequest, serverhttp.ResponseBadRequest{
			Code:    serverhttp.INVALIDSCHEMA,
			Details: helpers.Ptr([]string{err.Error()}),
		})
		if err != nil {
			return fmt.Errorf("ctx.JSON: %w", err)
		}

		return nil
	}

	err = h.S.PaymentService.CreatePayment(ctx.Request().Context(), &dto.CreatePaymentParams{
		ClaimID:         claimID,
		UserID:          params.XUserID,
		PaymentMethodID: req.PaymentMethodId,
	})
	if err != nil {
		switch {
		case errors.Is(err, service.ErrClaimNotFound):
			//nolint:wrapcheck
			return ctx.JSON(http.StatusNotFound, serverhttp.ResponseNotFound{
				Code: serverhttp.NOTFOUND,
				Details: &[]string{
					fmt.Sprintf("claim %s not found", claimID),
				},
			})

		default:
			return ctx.JSON(http.StatusInternalServerError, nil) //nolint:wrapcheck
		}
	}

	return ctx.JSON(http.StatusOK, nil) //nolint:wrapcheck
}

