func (s *Service) CreatePayment(ctx context.Context, params *dto.CreatePaymentParams) error {
	ctx, span := tracing.Start(ctx, "payment:CreatePayment")
	defer span.End()

	span.SetAttributes(
		attribute.Stringer("claim_id", params.ClaimID),
	)

	cl, err := s.claimRepo.GetUserClaimByClaimID(ctx, params.ClaimID, params.UserID)
	if err != nil {
		s.logger.Error(
			"failed to get claim",
			zap.String("claim_id", params.ClaimID.String()),
			zap.Error(err),
		)

		switch {
		case errors.Is(err, pgx.ErrNoRows):
			return errors.Join(service.ErrClaimNotFound, fmt.Errorf("s.claimRepo.GetClaimByClaimID: %w", err))
		default:
			return fmt.Errorf("s.claimRepo.GetClaimByClaimID: %w", err)
		}
	}

	if cl.State.Status != claim.StatusReadyForApproval {
		s.logger.Error(
			"claim is not ready for payment",
			zap.String("claim_id", params.ClaimID.String()),
			zap.Error(err),
			zap.Any("claim", cl),
		)

		return service.ErrInvalidState
	}

	info, err := s.lastmileOMSClient.C2CClaimInfo(ctx, cl.ClaimID, dto.Tariff(cl.Tariff))
	if err != nil {
		s.logger.Error(
			"failed to get claim info from last mile OMS",
			zap.String("claim_id", params.ClaimID.String()),
			zap.Error(err),
		)

		if errors.Is(err, infra.ErrBadRequest) {
			return service.ErrBadRequest
		}

		return fmt.Errorf("s.lastmileOMSClient.ClaimsInfo: %w", err)
	}

	createPaymentParams, err := infoToCreatePaymentParamsDTO(info)
	if err != nil {
		s.logger.Error(
			"failed to convert info to dto params",
			zap.String("claim_id", params.ClaimID.String()),
			zap.Error(err),
		)

		return fmt.Errorf("estimationToCreatePaymentParamsDTO: %w", err)
	}

	createPaymentParams.UserID = cl.UserID
	createPaymentParams.OrderCreatedAt = cl.CreatedAt
	createPaymentParams.PaymentMethodID = params.PaymentMethodID

	createPaymentParams.TotalSum = uint64(*info.Estimation.Cost) //nolint:gosec

	deliveryPrice := info.Estimation.BillingDetails.Route + info.Estimation.BillingDetails.Weight
	arrivalPrice := info.Estimation.BillingDetails.Arrival

	createPaymentParams.Services.Delivery.Price.Value = uint64(deliveryPrice) //nolint:gosec
	createPaymentParams.Services.Courier.Price.Value = uint64(arrivalPrice)   //nolint:gosec
	createPaymentParams.Email = cl.Email

	paymentReply, err := s.paymentProcessor.HoldPayment(ctx, createPaymentParams)
	if err != nil {
		s.logger.Error(
			"failed to create payment in payment processing",
			zap.String("claim_id", params.ClaimID.String()),
			zap.Error(err),
		)

		return fmt.Errorf("s.paymentProcessor.CreatePayment: %w", err)
	}

	_, err = s.paymentRepo.Create(ctx, &dto.CreateDBPaymentParams{
		ClaimID:         cl.ClaimID,
		OrderID:         paymentReply.OrderID,
		PaymentMethodID: params.PaymentMethodID,
		Client:          s.paymentProcessor.ClientID(),
		TotalCost:       int64(createPaymentParams.TotalSum),                      //nolint:gosec
		DeliveryCost:    int64(createPaymentParams.Services.Delivery.Price.Value), //nolint:gosec
		CourierCost:     int64(createPaymentParams.Services.Courier.Price.Value),  //nolint:gosec
	})
	if err != nil {
		s.logger.Error(
			"failed to create payment in database",
			zap.String("claim_id", params.ClaimID.String()),
			zap.Error(err),
		)

		return fmt.Errorf("s.paymentRepo.CreatePayment: %w", err)
	}

	s.logger.Info(
		"payment created",
		zap.String("claim_id", params.ClaimID.String()),
		zap.String("payment_id", paymentReply.PaymentID),
		zap.String("email", createPaymentParams.Email),
	)

	return nil
}

