func (c *Client) ClaimInfo(ctx context.Context, claimID uuid.UUID, partnerID string) (dto.Claim, error) {
	// TODO: подумать над переходом на ручку ClaimsList, где партнер не обязательный
	ctx, span := tracing.Start(ctx, "lastmileoms:ClaimInfo")
	defer span.End()

	span.SetAttributes(
		attribute.Stringer("claim_id", claimID),
	)

	log := c.logger.With(
		zap.String("http_client", "lm_oms"),
		zap.String("method", "claims_info"),
		zap.String("claim_id", claimID.String()),
	)

	req := lastmileomshttpclient.RequestClaimsInfo{
		ClaimIds: []uuid.UUID{
			claimID,
		},
	}

	resp, err := c.client.ClaimsInfoWithResponse(ctx, &lastmileomshttpclient.ClaimsInfoParams{
		Expand: &[]string{
			string(lastmileomshttpclient.ClaimsInfoParamsExpandBillingDetails),
			string(lastmileomshttpclient.ClaimsInfoParamsExpandPartnerId),
			string(lastmileomshttpclient.ClaimsInfoParamsExpandDropOffCode),
		},
		XPartnerID: partnerID,
	}, req)
	if err != nil {
		return dto.Claim{}, fmt.Errorf("c.client.ClaimsInfoWithResponse: %w", err)
	}

	switch resp.StatusCode() {
	case http.StatusOK:
		claims, err := toDtoClaims(resp.JSON200.Claims, c.tariffQuickPartnerID, c.tariffFourHoursPartnerID)
		if err != nil {
			return dto.Claim{}, fmt.Errorf("toDtoClaims: %w", err)
		}

		return claims[0], nil

	case http.StatusBadRequest:
		log.Error(
			"response code 400",
			zap.Any("details", helpers.Deref(resp.JSON400.Details)),
		)

		return dto.Claim{}, errors.Join(infra.ErrBadRequest, fmt.Errorf("%s", helpers.Deref(resp.JSON400.Details)))

	default:
		log.Error(
			"unhandled status code",
			zap.Int("status_code", resp.StatusCode()),
		)

		return dto.Claim{}, fmt.Errorf("unhandled status code: %d", resp.StatusCode())
	}
}

func Start(ctx context.Context, name string) (context.Context, trace.Span) {
	return tracer.Start(ctx, name)
}

func (c *ClientWithResponses) ClaimsInfoWithResponse(ctx context.Context, params *ClaimsInfoParams, body ClaimsInfoJSONRequestBody, reqEditors ...RequestEditorFn) (*ClaimsInfoResponse, error) {
	rsp, err := c.ClaimsInfo(ctx, params, body, reqEditors...)
	if err != nil {
		return nil, err
	}
	return ParseClaimsInfoResponse(rsp)
}

func ParseClaimsInfoResponse(rsp *http.Response) (*ClaimsInfoResponse, error) {
	bodyBytes, err := io.ReadAll(rsp.Body)
	defer func() { _ = rsp.Body.Close() }()
	if err != nil {
		return nil, err
	}

	response := &ClaimsInfoResponse{
		Body:         bodyBytes,
		HTTPResponse: rsp,
	}

	switch {
	case strings.Contains(rsp.Header.Get("Content-Type"), "json") && rsp.StatusCode == 200:
		var dest ResponseClaimsInfo
		if err := json.Unmarshal(bodyBytes, &dest); err != nil {
			return nil, err
		}
		response.JSON200 = &dest

	case strings.Contains(rsp.Header.Get("Content-Type"), "json") && rsp.StatusCode == 400:
		var dest ResponseBadRequest
		if err := json.Unmarshal(bodyBytes, &dest); err != nil {
			return nil, err
		}
		response.JSON400 = &dest

	case strings.Contains(rsp.Header.Get("Content-Type"), "json") && rsp.StatusCode == 404:
		var dest ResponseNotFound
		if err := json.Unmarshal(bodyBytes, &dest); err != nil {
			return nil, err
		}
		response.JSON404 = &dest

	case strings.Contains(rsp.Header.Get("Content-Type"), "json") && rsp.StatusCode == 409:
		var dest ResponseConflict
		if err := json.Unmarshal(bodyBytes, &dest); err != nil {
			return nil, err
		}
		response.JSON409 = &dest

	}

	return response, nil
}

func (r ClaimsInfoResponse) StatusCode() int {
	if r.HTTPResponse != nil {
		return r.HTTPResponse.StatusCode
	}
	return 0
}

func toDtoClaims(
	lmClaims []lastmileomshttpclient.Claim,
	quickTariffPartnerID, fourHoursTariffPartnerID dto.TariffGroup,
) ([]dto.Claim, error) {
	claims := make([]dto.Claim, len(lmClaims))

	for i, lmClaim := range lmClaims {
		if lmClaim.ClaimId == nil {
			// claim id нам не нужна
			continue
		}

		c, err := toDtoClaim(&lmClaim, quickTariffPartnerID, fourHoursTariffPartnerID)
		if err != nil {
			return nil, fmt.Errorf("toDtoClaim: %w", err)
		}

		claims[i] = c
	}

	return claims, nil
}

func toDtoClaim(
	lmClaim *lastmileomshttpclient.Claim,
	quickTariffPartnerID, fourHoursTariffPartnerID dto.TariffGroup,
) (dto.Claim, error) {
	var isBagRequired bool
	if lmClaim.IsBagRequired != nil {
		isBagRequired = *lmClaim.IsBagRequired
	}

	var courierInfo *dto.CourierInfo
	if lmClaim.CourierInfo != nil {
		courierInfo = &dto.CourierInfo{
			Latitude:  lmClaim.CourierInfo.Latitude,
			Longitude: lmClaim.CourierInfo.Longitude,
			Name:      lmClaim.CourierInfo.Name,
			Phone:     lmClaim.CourierInfo.Phone,
		}
	}

	var estimation *dto.Estimation

	if lmClaim.Estimation != nil {
		estimation = toDtoEstimation(lmClaim.Estimation)
	}

	meta, err := toDtoMeta(lmClaim.Meta)
	if err != nil {
		return dto.Claim{}, fmt.Errorf("failed to process meta: %w", err)
	}

	var needDropOffCode bool

	if lmClaim.NeedDropOffCode != nil {
		needDropOffCode = *lmClaim.NeedDropOffCode
	}

	var needReturn bool

	if lmClaim.NeedReturn != nil {
		needDropOffCode = *lmClaim.NeedReturn
	}

	var state dto.ClaimState

	if lmClaim.State != nil {
		state.Status = string(lmClaim.State.Status)

		if lmClaim.State.CancelReason != nil {
			state.CancelReason = &dto.CancelReason{
				Code:    lmClaim.State.CancelReason.Code,
				Message: lmClaim.State.CancelReason.Message,
			}
		}
	}

	tariff := dto.TariffQuick

	if lmClaim.PartnerId != nil {
		switch *lmClaim.PartnerId {
		case quickTariffPartnerID.NewUser:
			tariff = dto.TariffQuickNewUser
		case fourHoursTariffPartnerID.NewUser:
			tariff = dto.TariffFourHoursNewUser
		case fourHoursTariffPartnerID.Default:
			tariff = dto.TariffFourHours
		default:
			tariff = dto.TariffQuick
		}
	}

	return dto.Claim{
		ClaimID:         *lmClaim.ClaimId,
		Comment:         lmClaim.Comment,
		CourierInfo:     courierInfo,
		CreatedAt:       lmClaim.CreatedAt.TimeOrNil(),
		DueTime:         lmClaim.DueTime.TimeOrNil(),
		Estimation:      estimation,
		ExternalOrderId: lmClaim.ExternalOrderId,
		IsBagRequired:   isBagRequired,
		Items:           toDtoItems(lmClaim.Items),
		Meta:            meta,
		NeedDropOffCode: needDropOffCode,
		NeedReturn:      needReturn,
		RoutePoints:     toDtoRoutePoints(lmClaim.RoutePoints),
		State:           state,
		Tariff:          tariff,
		DropOffCode:     lmClaim.DropOffCode,
	}, nil
}

func toDtoEstimation(estimation *lastmileomshttpclient.Estimation) *dto.Estimation {
	var billingDetails *dto.BillingDetails
	if estimation.BillingDetails != nil {
		billingDetails = toDtoBillingDetails(estimation.BillingDetails)
	}

	return &dto.Estimation{
		Cost:                   estimation.Cost,
		Distance:               estimation.Distance,
		DropOffEta:             estimation.DropOffEta.TimeOrNil(),
		EstimatedArrival:       estimation.EstimatedArrival.TimeOrNil(),
		ExpectedCourierArrival: estimation.ExpectedCourierArrival.TimeOrNil(),
		PickupEta:              estimation.PickupEta.TimeOrNil(),
		BillingDetails:         billingDetails,
	}
}

func toDtoBillingDetails(details *lastmileomshttpclient.BillingDetails) *dto.BillingDetails {
	var bd dto.BillingDetails

	if details.ArrivalCost != nil {
		bd.Arrival = *details.ArrivalCost
	}

	if details.RouteCost != nil {
		bd.Route = *details.RouteCost
	}

	if details.WaitCost != nil {
		bd.Wait = *details.WaitCost
	}

	if details.WeightCost != nil {
		bd.Weight = *details.WeightCost
	}

	return &bd
}

func toDtoMeta(lmMeta *lastmileomshttpclient.Claim_Meta) (json.RawMessage, error) {
	if lmMeta == nil {
		return nil, nil
	}

	bytes, err := lmMeta.MarshalJSON()
	if err != nil {
		return nil, fmt.Errorf("lmMeta.MarshalJSON: %w", err)
	}

	var meta json.RawMessage

	err = meta.UnmarshalJSON(bytes)
	if err != nil {
		return nil, fmt.Errorf("lmMeta.MarshalJSON: %w", err)
	}

	return meta, nil
}

func (t Claim_Meta) MarshalJSON() ([]byte, error) {
	b, err := t.union.MarshalJSON()
	return b, err
}

func toDtoItems(lmItems lastmileomshttpclient.Items) dto.Items {
	items := dto.Items{
		Cost:      lmItems.Cost,
		Weight:    lmItems.Weight,
		ItemsInfo: nil,
	}

	if lmItems.ItemsInfo != nil {
		itemsInfo := make([]dto.ItemInfo, 0, len(*lmItems.ItemsInfo))

		for _, itemInfo := range *lmItems.ItemsInfo {
			itemsInfo = append(itemsInfo, dto.ItemInfo{
				Depth:  itemInfo.Depth,
				Height: itemInfo.Height,
				Width:  itemInfo.Width,
				Name:   itemInfo.Name,
				Price:  itemInfo.Price,
			})
		}

		items.ItemsInfo = itemsInfo
	}

	return items
}

func toDtoRoutePoints(lmRoutePoints []lastmileomshttpclient.RoutePoint) []dto.RoutePoint {
	routePoints := make([]dto.RoutePoint, len(lmRoutePoints))

	for i, rp := range lmRoutePoints {
		routePoints[i] = dto.RoutePoint{
			Address: &dto.Address{
				Comment: rp.Address.Comment,
				Coordinates: &dto.Coordinates{
					Lat: rp.Address.Coordinates.Lat,
					Lon: rp.Address.Coordinates.Lon,
				},
				DoorCode: rp.Address.DoorCode,
				Flat:     rp.Address.Flat,
				Floor:    rp.Address.Floor,
				FullName: rp.Address.FullName,
				Porch:    rp.Address.Porch,
			},
			Contact: &dto.Contact{
				ExtensionNumber: rp.Contact.ExtensionNumber,
				ExtraPhone:      rp.Contact.ExtraPhone,
				Name:            rp.Contact.Name,
				Phone:           rp.Contact.Phone,
			},
			Type: dto.RoutePointType(rp.PointType),
		}
	}

	return routePoints
}

