func infoToCreatePaymentParamsDTO(info dto.Claim) (*dto.HoldPaymentParams, error) {
	if info.Estimation == nil {
		return nil, errors.New("no estimation for claim")
	}

	if info.Estimation.Cost == nil {
		return nil, errors.New("no cost in estimation")
	}

	if info.Estimation.BillingDetails == nil {
		return nil, errors.New("no billing details in estimation")
	}

	pickupPoint, err := getPickupPoint(info.RoutePoints)
	if err != nil {
		return nil, fmt.Errorf("getPickupPoint: %w", err)
	}

	return &dto.HoldPaymentParams{
		OrderID:         info.ExternalOrderId,
		TotalSum:        0,
		UserID:          "",
		Phone:           pickupPoint.Contact.Phone,
		OrderCreatedAt:  time.Time{},
		PaymentMethodID: "",
		StoreCode:       defaultStoreCode,
		Source:          defatulSource,
		Email:           "",
		Services: dto.PaymentServices{
			Delivery: &dto.PaymentServiceDelivery{
				Price: dto.PaymentPrice{
					Value: 0,
				},
			},
			Courier: &dto.PaymentServiceCourier{
				Price: dto.PaymentPrice{
					Value: 0,
				},
			},
		},
	}, nil
}

func getPickupPoint(routePoints []dto.RoutePoint) (dto.RoutePoint, error) {
	for _, p := range routePoints {
		if p.Type == dto.RouteTypeSource {
			return p, nil
		}
	}

	return dto.RoutePoint{}, fmt.Errorf("no pickup point in route points")
}

