func (h *Handlers) ClaimStatus(
	c echo.Context,
	claimID serverhttp.ClaimID,
	params serverhttp.ClaimStatusParams,
) error {
	cl, err := h.S.ClaimService.GetUserClaimByClaimID(c.Request().Context(), params.XUserID, claimID)
	if err != nil {
		switch {
		case errors.Is(err, service.ErrClaimNotFound):
			//nolint:wrapcheck
			return c.JSON(http.StatusNotFound, serverhttp.ResponseNotFound{
				Code: "not_found",
				Details: &[]string{
					fmt.Sprintf("claim with id %s not found", claimID),
				},
			})
		default:
			return c.JSON(http.StatusInternalServerError, nil) //nolint:wrapcheck
		}
	}

	resp := serverhttp.ClaimState{
		Status:       serverhttp.ClaimStatus(cl.State.Status),
		CancelReason: nil,
	}

	if cl.State.CancelReason != nil {
		resp.CancelReason = &serverhttp.CancelReason{
			Code:    string(cl.State.CancelReason.Code),
			Message: nil,
		}

		if cl.State.CancelReason.Message != nil {
			msg := string(*cl.State.CancelReason.Message)
			resp.CancelReason.Message = &msg
		}
	}

	return c.JSON(http.StatusOK, resp) //nolint:wrapcheck
}

