func (h *Handlers) GetUserShippings(c echo.Context, params serverhttp.GetUserShippingsParams) error {
	pageSize := hardLimit
	if params.PageSize != nil && *params.PageSize > 0 {
		pageSize = *params.PageSize
	}

	if pageSize > hardLimit {
		pageSize = hardLimit
	}

	page := 1
	if params.Page != nil && *params.Page > 0 {
		page = *params.Page
	}

	sortDirection := dto.SortDirectionDesc

	if params.OrderDirection != nil && string(*params.OrderDirection) == string(serverhttp.QueryOrderDirectionAcs) {
		sortDirection = dto.SortDirectionAsc
	}

	data, err := h.S.TrackingLinkService.GetShippings(c.Request().Context(), dto.GetShippingParams{
		MagnitID:      params.XUserId,
		Page:          page,
		PageSize:      pageSize,
		SortDirection: sortDirection,
	})

	l := logger.FromContext(c.Request().Context()).
		With(zap.String("magnit_id", params.XUserId))

	if err != nil {
		if errors.Is(err, trackingLink.ErrShippingsNotFound) {
			//nolint:wrapcheck
			return c.JSON(http.StatusNotFound, serverhttp.ResponseNotFound{
				Code: serverhttp.NOTFOUND,
				Details: &[]string{
					"no shippings found",
				},
			})
		}

		l.Error("failed to get user shippings", zap.Error(err))

		return c.JSON(http.StatusInternalServerError, nil) //nolint:wrapcheck
	}

	var resp serverhttp.ResponseGetShippings

	for _, shipping := range data {
		var trackingData serverhttp.ResponseGetTrackingData

		trackingData.Source = serverhttp.TrackSource(shipping.Source)

		switch shipping.Source {
		case dto.TrackingLinkSourceC2C, dto.TrackingLinkSourceOMS:
			err = fillLastMileTrackingData(&trackingData, shipping.LastMileTrackingData, false)

		case dto.TrackingLinkSourcePost:
			err = fillMagnitPostData(&trackingData, shipping.MagnitPostTrackingData, false)

		case dto.TrackingLinkSourceUnspecified:
			err = errors.New("tracking link not found")
		}

		if err != nil {
			l.Error("failed transform user shippings into http response", zap.Error(err))

			continue
		}

		resp = append(resp, trackingData)
	}

	return c.JSON(http.StatusOK, resp) //nolint:wrapcheck
}

func (s *Service) GetShippings(ctx context.Context, params dto.GetShippingParams) ([]dto.TrackingData, error) {
	trackLinks, err := s.repository.TrackingLink.GetTrackingLinksByMagnitID(ctx, params)
	if err != nil {
		if errors.Is(err, tracking_link.ErrTrackingLinkNotFound) {
			return nil, ErrShippingsNotFound
		}

		return nil, fmt.Errorf("s.repository.TrackingLink.GetTrackingLinksByMagnitID: %w", err)
	}

	// мапа для восстановления порядка сообщений
	indexes := make(map[string]int, len(trackLinks))

	postOrders := make([]*dto.TrackingLink, 0, len(trackLinks))
	lmOrders := make([]*dto.TrackingLink, 0, len(trackLinks))
	c2cOrders := make([]*dto.TrackingLink, 0, len(trackLinks))

	for i, link := range trackLinks {
		indexes[link.ClaimID.String()] = i

		switch link.Source {
		case dto.TrackingLinkSourceUnspecified:
			continue

		case dto.TrackingLinkSourceOMS:
			lmOrders = append(lmOrders, link)

		case dto.TrackingLinkSourceC2C:
			c2cOrders = append(c2cOrders, link)

		case dto.TrackingLinkSourcePost:
			postOrders = append(postOrders, link)
		}
	}

	g, gCtx := errgroup.WithContext(ctx)

	var (
		lmData   []dto.TrackingData
		c2cData  []dto.TrackingData
		postData []dto.TrackingData
	)

	g.Go(func() error {
		var gErr error
		if lmData, gErr = getData(gCtx, lmOrders, s.lastMileOMSClient.ClaimsList); gErr != nil {
			return gErr
		}

		return nil
	})

	g.Go(func() error {
		var gErr error
		if c2cData, gErr = getData(gCtx, c2cOrders, s.lastMileOMSClient.ClaimsList); gErr != nil {
			return gErr
		}

		return nil
	})

	g.Go(func() error {
		var gErr error
		if postData, gErr = getData(gCtx, postOrders, s.magnitPostClient.GetOrdersInfoByIdsV2); gErr != nil {
			return gErr
		}

		return nil
	})

	if gErr := g.Wait(); gErr != nil {
		return nil, fmt.Errorf("failed to fetch data: %w", gErr)
	}

	data := restoreOrder(
		indexes,
		lmData,
		c2cData,
		postData,
	)

	// проставляем partnerDisplayName и Source
	for i, d := range data {
		data[i].Source = trackLinks[i].Source

		partnerDisplayName := trackLinks[i].DisplayName

		if d.LastMileTrackingData != nil && partnerDisplayName != nil {
			d.LastMileTrackingData.PartnerDisplayName = *partnerDisplayName
		}

		if d.MagnitPostTrackingData != nil && partnerDisplayName != nil {
			if d.MagnitPostTrackingData.OrderInfoV2.TrackingNumber != "" {
				d.MagnitPostTrackingData.OrderInfoV2.PartnerDisplayName = *partnerDisplayName
			}

			if d.MagnitPostTrackingData.OrderInfo.TrackingNumber != "" {
				d.MagnitPostTrackingData.OrderInfo.PartnerDisplayName = *partnerDisplayName
			}
		}
	}

	return data, nil
}

func (r *Repository) GetTrackingLinksByMagnitID(
	ctx context.Context,
	params dto.GetShippingParams,
) ([]*dto.TrackingLink, error) {
	offset := (params.Page - 1) * params.PageSize

	links, err := r.slave.GetTrackingLinksByMagnitID(ctx, queries.GetTrackingLinksByMagnitIDParams{
		MagnitID:      &params.MagnitID,
		SortDirection: &params.SortDirection,
		Offset:        helpers.Ptr(int32(offset)),          //nolint:gosec
		Limit:         helpers.Ptr(int32(params.PageSize)), //nolint:gosec
	})
	if err != nil {
		if errors.Is(err, sql.ErrNoRows) {
			return nil, ErrTrackingLinkNotFound
		}

		return nil, fmt.Errorf("r.slave.GetTrackingLinksByMagnitID: %w", err)
	}

	out := make([]*dto.TrackingLink, 0, len(links))

	for _, link := range links {
		out = append(out, LinkToDomain(&link))
	}

	return out, nil
}

