func getData[T any](
	ctx context.Context,
	links []*dto.TrackingLink,
	getFn func(context.Context, []uuid.UUID) ([]T, error),
) ([]dto.TrackingData, error) {
	if len(links) == 0 {
		return nil, nil
	}

	claimIDs := make([]uuid.UUID, 0, len(links))

	for _, l := range links {
		claimIDs = append(claimIDs, l.ClaimID)
	}

	claims, err := getFn(ctx, claimIDs)
	if err != nil {
		return nil, fmt.Errorf("failed to get data: %w", err)
	}

	out := make([]dto.TrackingData, 0, len(claims))

	for _, claim := range claims {
		data, err := toTrackingData(claim)
		if err != nil {
			return nil, fmt.Errorf("toTrackingData: %w", err)
		}

		out = append(out, data)
	}

	return out, nil
}

