	if r.HTTPResponse != nil {
		return r.HTTPResponse.StatusCode
	}
	return 0
}

func toDtoClaims(
	lmClaims []lastmileomshttpclient.Claim,
	quickTariffPartnerID, fourHoursTariffPartnerID dto.TariffGroup,
) ([]dto.Claim, error) {
	claims := make([]dto.Claim, len(lmClaims))

	for i, lmClaim := range lmClaims {
		if lmClaim.ClaimId == nil {
			// claim id нам не нужна
			continue
		}

		c, err := toDtoClaim(&lmClaim, quickTariffPartnerID, fourHoursTariffPartnerID)
		if err != nil {
			return nil, fmt.Errorf("toDtoClaim: %w", err)
		}

		claims[i] = c
	}

	return claims, nil
}

func toDtoClaim(
	lmClaim *lastmileomshttpclient.Claim,
	quickTariffPartnerID, fourHoursTariffPartnerID dto.TariffGroup,
) (dto.Claim, error) {
	var isBagRequired bool
	if lmClaim.IsBagRequired != nil {
		isBagRequired = *lmClaim.IsBagRequired
	}

	var courierInfo *dto.CourierInfo
	if lmClaim.CourierInfo != nil {
		courierInfo = &dto.CourierInfo{
			Latitude:  lmClaim.CourierInfo.Latitude,
			Longitude: lmClaim.CourierInfo.Longitude,
			Name:      lmClaim.CourierInfo.Name,
			Phone:     lmClaim.CourierInfo.Phone,
		}
	}

	var estimation *dto.Estimation

	if lmClaim.Estimation != nil {
		estimation = toDtoEstimation(lmClaim.Estimation)
	}

	meta, err := toDtoMeta(lmClaim.Meta)
	if err != nil {
		return dto.Claim{}, fmt.Errorf("failed to process meta: %w", err)
	}

	var needDropOffCode bool

	if lmClaim.NeedDropOffCode != nil {
		needDropOffCode = *lmClaim.NeedDropOffCode
	}

	var needReturn bool

	if lmClaim.NeedReturn != nil {
		needDropOffCode = *lmClaim.NeedReturn
	}

	var state dto.ClaimState

	if lmClaim.State != nil {
		state.Status = string(lmClaim.State.Status)

		if lmClaim.State.CancelReason != nil {
			state.CancelReason = &dto.CancelReason{
				Code:    lmClaim.State.CancelReason.Code,
				Message: lmClaim.State.CancelReason.Message,
			}
		}
	}

	tariff := dto.TariffQuick

	if lmClaim.PartnerId != nil {
		switch *lmClaim.PartnerId {
		case quickTariffPartnerID.NewUser:
			tariff = dto.TariffQuickNewUser
		case fourHoursTariffPartnerID.NewUser:
			tariff = dto.TariffFourHoursNewUser
		case fourHoursTariffPartnerID.Default:
			tariff = dto.TariffFourHours
		default:
			tariff = dto.TariffQuick
		}
	}

	return dto.Claim{
		ClaimID:         *lmClaim.ClaimId,
		Comment:         lmClaim.Comment,
		CourierInfo:     courierInfo,
		CreatedAt:       lmClaim.CreatedAt.TimeOrNil(),
		DueTime:         lmClaim.DueTime.TimeOrNil(),
		Estimation:      estimation,
		ExternalOrderId: lmClaim.ExternalOrderId,
		IsBagRequired:   isBagRequired,
		Items:           toDtoItems(lmClaim.Items),
		Meta:            meta,
		NeedDropOffCode: needDropOffCode,
		NeedReturn:      needReturn,
		RoutePoints:     toDtoRoutePoints(lmClaim.RoutePoints),
		State:           state,
		Tariff:          tariff,
		DropOffCode:     lmClaim.DropOffCode,
	}, nil
}

func toDtoEstimation(estimation *lastmileomshttpclient.Estimation) *dto.Estimation {
	var billingDetails *dto.BillingDetails
	if estimation.BillingDetails != nil {
		billingDetails = toDtoBillingDetails(estimation.BillingDetails)
	}

	return &dto.Estimation{
		Cost:                   estimation.Cost,
		Distance:               estimation.Distance,
		DropOffEta:             estimation.DropOffEta.TimeOrNil(),
		EstimatedArrival:       estimation.EstimatedArrival.TimeOrNil(),
		ExpectedCourierArrival: estimation.ExpectedCourierArrival.TimeOrNil(),
		PickupEta:              estimation.PickupEta.TimeOrNil(),
		BillingDetails:         billingDetails,
	}
}

func toDtoBillingDetails(details *lastmileomshttpclient.BillingDetails) *dto.BillingDetails {
	var bd dto.BillingDetails

	if details.ArrivalCost != nil {
		bd.Arrival = *details.ArrivalCost
	}

	if details.RouteCost != nil {
		bd.Route = *details.RouteCost
	}

	if details.WaitCost != nil {
		bd.Wait = *details.WaitCost
	}

	if details.WeightCost != nil {
		bd.Weight = *details.WeightCost
	}

	return &bd
}

func toDtoMeta(lmMeta *lastmileomshttpclient.Claim_Meta) (json.RawMessage, error) {
	if lmMeta == nil {
		return nil, nil
	}

	bytes, err := lmMeta.MarshalJSON()
	if err != nil {
		return nil, fmt.Errorf("lmMeta.MarshalJSON: %w", err)
	}

	var meta json.RawMessage

	err = meta.UnmarshalJSON(bytes)
	if err != nil {
		return nil, fmt.Errorf("lmMeta.MarshalJSON: %w", err)
	}

	return meta, nil
}

