func fillMagnitPostData(
	response *serverhttp.ResponseGetTrackingData,
	data *dto.PostTrackingData,
	short bool,
) error {
	if data == nil {
		return errors.New("no data found")
	}

	if data.V1NotSupported {
		return ErrV1NotSupported
	}

	workingHours := make([]serverhttp.DayWorkHours, 0)

	for _, wh := range data.Pup.WorkHours {
		workingHours = append(workingHours, serverhttp.DayWorkHours{
			Day:  serverhttp.Week(wh.Weekday),
			From: wh.From,
			Till: wh.Till,
		})
	}

	d := serverhttp.PostData{
		Barcode:     data.OrderInfo.CustomerOrderID,
		ShortId:     helpers.ShortID(data.OrderInfo.TrackingNumber),
		IssueCode:   nil,
		PartnerName: data.OrderInfo.PartnerDisplayName,
		PickupPoint: serverhttp.PostPickupPoint{
			Address:      data.Pup.Address,
			WorkingHours: workingHours,
		},
		Status:         serverhttp.PostOrderStatus(data.OrderInfo.OrderStatus),
		StorageEndDate: data.OrderInfo.StorageEndDate,
	}

	if !short {
		d.IssueCode = data.OrderInfo.IssueCode
	}

	if err := response.Data.FromPostData(d); err != nil {
		return fmt.Errorf("response.Data.FromPostData: %w", err)
	}

	return nil
}

