func restoreOrder(
	indexes map[string]int,
	input ...[]dto.TrackingData,
) []dto.TrackingData {
	length := 0
	for _, d := range input {
		length += len(d)
	}

	data := make([]dto.TrackingData, 0, length)

	for _, d := range input {
		data = append(data, d...)
	}

	sort.Slice(data, func(i, j int) bool {
		iClaimID := getClaimID(data[i])
		jClaimID := getClaimID(data[j])

		iIdx, iOk := indexes[iClaimID]
		jIdx, jOk := indexes[jClaimID]

		if !iOk || !jOk {
			return false
		}

		return iIdx < jIdx
	})

	return data
}

