func toTrackingData(info any) (dto.TrackingData, error) {
	switch v := info.(type) {
	case dto.Claim:
		data, err := infoToLastMileTrackingData(v)
		if err != nil {
			return dto.TrackingData{}, fmt.Errorf("s.lastMileOMSClient.ClaimsList: %w", err)
		}

		return dto.TrackingData{
			Source:                 dto.TrackingLinkSourceOMS,
			MagnitID:               nil,
			LastMileTrackingData:   &data,
			MagnitPostTrackingData: nil,
		}, nil

	case dto.PostOrderInfo:
		return dto.TrackingData{
			Source:               dto.TrackingLinkSourcePost,
			MagnitID:             nil,
			LastMileTrackingData: nil,
			MagnitPostTrackingData: &dto.PostTrackingData{ //nolint:exhaustruct
				OrderInfo: v,
				// из ручки можем получить только адрес и ключ ПВЗ
				Pup: dto.PickupPoint{
					Key:       v.Delivery.PickupPointKey,
					Name:      "",
					Type:      "",
					Address:   v.Delivery.PickupPointAddress,
					Region:    nil,
					City:      nil,
					Index:     nil,
					WorkHours: nil,
				},
			},
		}, nil

	case dto.PostOrderInfoV2:
		pd := &dto.PostTrackingData{ //nolint:exhaustruct
			OrderInfoV2: v,
			Pup: dto.PickupPoint{ //nolint:exhaustruct
				Key:     v.Delivery.PickupPointKey,
				Address: v.Delivery.PickupPointAddress,
			},
		}

		// если одна посылка — мапим в V1, иначе ставим флаг
		if len(v.Parcels) == 1 {
			pd.OrderInfo = mapV2ToV1(v)
		} else {
			pd.V1NotSupported = true
		}

		return dto.TrackingData{
			Source:                 dto.TrackingLinkSourcePost,
			MagnitID:               nil,
			LastMileTrackingData:   nil,
			MagnitPostTrackingData: pd,
		}, nil
	}

	return dto.TrackingData{}, errors.New("unsupported type")
}

func infoToLastMileTrackingData(info dto.Claim) (dto.LastMileTrackingData, error) {
	var out dto.LastMileTrackingData

	out.ClaimID = info.ClaimID
	out.NeedDropOffCode = info.NeedDropOffCode
	out.Weight = info.Items.Weight
	out.Cost = info.Items.Cost
	out.ExternalOrderID = info.ExternalOrderId
	out.DropOffCode = info.DropOffCode

	if info.Estimation != nil {
		if info.Estimation.EstimatedArrival != nil {
			out.EstimatedArrival = info.Estimation.EstimatedArrival
		}

		if info.Estimation.ExpectedCourierArrival != nil {
			out.ExpectedCourierArrival = info.Estimation.ExpectedCourierArrival
		}
	}

	out.State = info.State
	out.CourierInfo = info.CourierInfo

	srcPointIdx := slices.IndexFunc(info.RoutePoints, func(p dto.RoutePoint) bool {
		return p.Type == dto.RouteTypeSource
	})

	if srcPointIdx == -1 {
		return dto.LastMileTrackingData{}, fmt.Errorf("source route point not found")
	}

	dstPointIdx := slices.IndexFunc(info.RoutePoints, func(p dto.RoutePoint) bool {
		return p.Type == dto.RouteTypeDestination
	})

	if dstPointIdx == -1 {
		return dto.LastMileTrackingData{}, fmt.Errorf("destination route point not found")
	}

	out.SrcPoint = info.RoutePoints[srcPointIdx]
	out.DstPoint = info.RoutePoints[dstPointIdx]

	return out, nil
}

srcPointIdx := slices.IndexFunc(info.RoutePoints, func(p dto.RoutePoint) bool {
