func fillMagnitPostDataV2(
	response *serverhttp.ResponseGetTrackingDataV2,
	data *dto.PostTrackingData,
	short bool,
) error {
	if data == nil {
		return errors.New("no data found")
	}

	workingHours := make([]serverhttp.DayWorkHours, 0)

	for _, wh := range data.Pup.WorkHours {
		workingHours = append(workingHours, serverhttp.DayWorkHours{
			Day:  serverhttp.Week(wh.Weekday),
			From: wh.From,
			Till: wh.Till,
		})
	}

	// собираем посылки
	parcels := make([]serverhttp.Parcel, 0, len(data.OrderInfoV2.Parcels))

	for _, p := range data.OrderInfoV2.Parcels {
		parcels = append(parcels, serverhttp.Parcel{
			Barcode:        p.Barcode,
			Status:         serverhttp.PostOrderStatus(p.Status),
			StorageEndDate: p.StorageEndDate,
		})
	}

	d := serverhttp.PostDataV2{ //nolint:exhaustruct
		CustomerOrderId: data.OrderInfoV2.CustomerOrderID,
		ShortId:         helpers.ShortID(data.OrderInfoV2.TrackingNumber),
		PartnerName:     data.OrderInfoV2.PartnerDisplayName,
		PickupPoint: serverhttp.PostPickupPoint{
			Address:      data.Pup.Address,
			WorkingHours: workingHours,
		},
		Parcels: &parcels,
	}

	if !short {
		d.IssueCode = data.OrderInfoV2.IssueCode
	}

	if err := response.Data.FromPostDataV2(d); err != nil {
		return fmt.Errorf("response.Data.FromPostDataV2: %w", err)
	}

	return nil
}

