	if err == nil || len(grpcErr) < 1 {
		return false
	}

	statusErr, ok := status.FromError(err)
	if !ok {
		return false
	}

	for _, detail := range statusErr.Details() {
		reason, ok := detail.(*errdetails.ErrorInfo)
		if !ok {
			continue
		}

		for _, e := range grpcErr {
			if reason.Reason == e.String() {
				return true
			}
		}
	}

	return false
}

