func (h *Handlers) Refund(c echo.Context, claimID serverhttp.ClaimID) error {
	var req serverhttp.RequestRefund

	if err := c.Bind(&req); err != nil {
		//nolint:wrapcheck
		return c.JSON(http.StatusBadRequest, serverhttp.ResponseBadRequest{
			Code: serverhttp.INVALIDSCHEMA,
			Details: &[]string{
				err.Error(),
			},
		})
	}

	if err := validate.V().Struct(req); err != nil {
		//nolint:wrapcheck
		return c.JSON(http.StatusBadRequest, serverhttp.ResponseBadRequest{
			Code: serverhttp.INVALIDSCHEMA,
			Details: &[]string{
				err.Error(),
			},
		})
	}

	var (
		details dto.RefundDetails
		err     error
	)

	switch req.Service {
	case serverhttp.CourierService:
		details, err = h.S.PaymentService.RefundCourierService(c.Request().Context(), claimID)

	case serverhttp.DeliveryService:
		details, err = h.S.PaymentService.RefundDeliveryService(c.Request().Context(), claimID)

	case serverhttp.AllServices:
		details, err = h.S.PaymentService.RefundAll(c.Request().Context(), claimID)
	}

	if err != nil {
		if errors.Is(err, payment.ErrPaymentNotFound) ||
			errors.Is(err, payment.ErrPaymentMethodNotFound) {
			return c.JSON(http.StatusNotFound, serverhttp.ResponseNotFound{ //nolint:wrapcheck
				Code: serverhttp.NOTFOUND,
				Details: &[]string{
					err.Error(),
				},
			})
		}

		//nolint:wrapcheck
		return c.JSON(http.StatusInternalServerError, serverhttp.ResponseError{
			Code: "internal server error",
			Details: &[]string{
				err.Error(),
			},
		})
	}

	//nolint:wrapcheck
	return c.JSON(http.StatusOK, toRefundHTTPResponse(details))
}

