func (s *Service) RefundDeliveryService(ctx context.Context, claimID uuid.UUID) (dto.RefundDetails, error) {
	ctx, span := tracing.Start(ctx, "payment:RefundDeliveryService")
	defer span.End()

	span.SetAttributes(
		attribute.Stringer("claim_id", claimID),
	)

	log := s.logger.With(
		zap.String("claim_id", claimID.String()),
	)

	details, err := s.refund(
		ctx,
		claimID,
		&dto.PaymentServiceDelivery{}, //nolint:exhaustruct
		nil,
	)
	if err != nil {
		log.Error("failed to refund delivery service", zap.Error(err))

		return details, err
	}

	log.Info("refund delivery service")

	return details, nil
}

