func (s *Service) refund(
	ctx context.Context,
	claimID uuid.UUID,
	deliveryService *dto.PaymentServiceDelivery,
	courierService *dto.PaymentServiceCourier,
) (dto.RefundDetails, error) {
	var details dto.RefundDetails

	log := s.logger.With(
		zap.String("claim_id", claimID.String()),
	)

	payment, err := s.paymentRepo.GetPaymentForClaim(ctx, claimID)
	if err != nil {
		log.Error("failed to refund all services", zap.Error(err))

		switch {
		case errors.Is(err, paymentRepo.ErrPaymentNotFound):
			return details, ErrPaymentNotFound

		default:
			return details, fmt.Errorf("s.paymentRepo.GetPaymentForClaim: %w", err)
		}
	}

	if payment.RefundID == nil {
		refundID, err := helpers.GenerateRefundId()
		if err != nil {
			log.Error("failed to refund all services", zap.Error(err))

			return details, fmt.Errorf("helpers.GenerateRefundId: %w", err)
		}

		payment.RefundID = &refundID
	}

	if deliveryService != nil {
		deliveryService.Price.Value = uint64(payment.DeliveryCost)
	}

	if courierService != nil {
		courierService.Price.Value = uint64(payment.CourierCost)
	}

	log = log.With(
		zap.String("refund_id", *payment.RefundID),
	)

	params := &dto.RefundParams{
		OrderID:         payment.OrderID,
		RefundID:        *payment.RefundID,
		Client:          payment.Client,
		DeliveryService: deliveryService,
		CourierService:  courierService,
		TotalSum:        uint64(payment.TotalCost),
	}

	_, err = s.paymentProcessor.Refund(ctx, params)
	if err != nil {
		switch {
		case errors.Is(err, paymentClient.ErrOperationNotAllowed):
			return details, ErrOperationNotAllowed

		case errors.Is(err, paymentClient.ErrPaymentCartNotFound):
			return details, ErrPaymentCartNotFound

		case errors.Is(err, paymentClient.ErrValidationError):
			return details, ErrValidationError

		case errors.Is(err, paymentClient.ErrPaymentMethodNotFound):
			return details, ErrPaymentMethodNotFound

		case errors.Is(err, paymentClient.ErrPaymentMethodNotAvailable):
			return details, ErrPaymentMethodNotAvailable

		case errors.Is(err, paymentClient.ErrPaymentNotFound):
			return details, ErrPaymentNotFound

		default:
			return details, fmt.Errorf("s.paymentProcessor.Refund: %w", err)
		}
	}

	log.Info("payment processing call ok")

	payment.Status = string(dto.PaymentToRefund)

	_, err = s.paymentRepo.Save(ctx, payment)
	if err != nil {
		return details, fmt.Errorf("s.paymentRepo.Save: %w", err)
	}

	deliveryCost := uint64(payment.DeliveryCost)
	courierCost := uint64(payment.CourierCost)

	details.OrderID = payment.OrderID
	details.RefundID = *payment.RefundID
	details.TotalSum = uint64(payment.TotalCost)

	if deliveryService != nil {
		details.DeliveryPrice = &deliveryCost
	}

	if courierService != nil {
		details.CourierPrice = &courierCost
	}

	return details, nil
}

