				Currency: genGRPC.CurrencyEnum_RUB,
				Value:    params.CourierService.Price.Value,
			},
		}
	}

	reply, err := c.client.PMSService.RefundV3(ctx, &req)
	if err != nil {
		switch {
		case genGRPC.IsErr(err, genGRPC.ActionV2Reply_VALIDATION_ERROR):
			return nil, ErrValidationError

		case genGRPC.IsErr(err, genGRPC.ActionV2Reply_OPERATION_NOT_ALLOWED):
			return nil, ErrOperationNotAllowed

		case genGRPC.IsErr(err, genGRPC.ActionV2Reply_PAYMENT_METHOD_NOT_FOUND):
			return nil, ErrPaymentMethodNotFound

		case genGRPC.IsErr(err, genGRPC.ActionV2Reply_PAYMENT_METHOD_NOT_AVAILABLE):
			return nil, ErrPaymentMethodNotAvailable

		case genGRPC.IsErr(err, genGRPC.ActionV2Reply_PAYMENT_NOT_FOUND):
			return nil, ErrPaymentMethodNotFound

		case genGRPC.IsErr(err, genGRPC.ActionV2Reply_CART_NOT_FOUND):
			return nil, ErrPaymentCartNotFound

		default:
			return nil, fmt.Errorf("c.client.PMSService.RefundV3: %w", err)
