func makeComment(params *dto.CreateClaimParams) *string {
	srcPoint := params.RoutePoints[0]
	if params.RoutePoints[1].Type == dto.RouteTypeSource {
		srcPoint = params.RoutePoints[1]
	}

	comment := commentTemplate

	if srcPoint.Contact.Name != nil {
		comment += fmt.Sprintf("%s, ", *srcPoint.Contact.Name)
	}

	comment += srcPoint.Contact.Phone
	if srcPoint.Address.Comment != nil {
		comment += fmt.Sprintf("\n%s", *srcPoint.Address.Comment)
	}

	return &comment
}

