func (h *Handlers) EstimateClaim(c echo.Context) error {
	var req serverhttp.RequestEstimateClaim

	if err := c.Bind(&req); err != nil {
		//nolint:wrapcheck
		return c.JSON(http.StatusBadRequest, serverhttp.ResponseBadRequest{
			Code: serverhttp.INVALIDSCHEMA,
			Details: &[]string{
				err.Error(),
			},
		})
	}

	if err := validate.V().StructCtx(c.Request().Context(), req); err != nil {
		//nolint:wrapcheck
		return c.JSON(http.StatusBadRequest, serverhttp.ResponseBadRequest{
			Code: serverhttp.INVALIDSCHEMA,
			Details: &[]string{
				err.Error(),
			},
		})
	}

	estimateClaimParams := dto.ToDTOEstimateClaimParams(&req)

	estimation, err := h.S.ClaimService.EstimateClaim(c.Request().Context(), estimateClaimParams)

	var httpErr infra.HTTPError

	switch {
	case err == nil:
		return c.JSON(http.StatusOK, toHTTPEstimationResponse(estimation)) //nolint:wrapcheck
	case errors.Is(err, infra.ErrBadRequest):
		//nolint:wrapcheck
		return c.JSON(http.StatusBadRequest, serverhttp.ResponseBadRequest{
			Code: serverhttp.INVALIDSCHEMA,
			Details: &[]string{
				err.Error(),
			},
		})
	case errors.As(err, &httpErr):
		//nolint:wrapcheck
		return c.JSON(http.StatusBadRequest, serverhttp.ResponseBadRequest{
			Code: serverhttp.OTHERVALIDATIONERRORS,
			Details: &[]string{
				httpErr.Message,
			},
		})

	default:
		//nolint:wrapcheck
		return c.JSON(http.StatusInternalServerError, nil)
	}
}

