func (s *Service) ClaimsInfo(ctx context.Context, params *dto.ClaimsInfoParams) (dto.ClaimsInfo, error) {
	ctx, span := tracing.Start(ctx, "claim:ClaimsInfo")
	defer span.End()

	queryContext, cancelQuery := context.WithTimeout(ctx, queryTimeout)

	defer cancelQuery()

	g, gCtx := errgroup.WithContext(queryContext)

	var claimsInfo []dto.Claim

	g.Go(func() error {
		claims, err := s.repo.GetUserClaimByClaimIDs(gCtx, params.ClaimIds, params.UserID)
		if err != nil {
			s.logger.Error("failed to check claims", zap.Error(err))

			switch {
			case errors.Is(err, claim.ErrClaimNotFound):
				return service.ErrClaimNotFound

			default:
				return fmt.Errorf("s.repo.GetUserClaimByClaimIDs: %w", err)
			}
		}

		// если пользователь передал claim id, который ему не принадлежит, то вырезаем его
		for _, c := range claims {
			params.ClaimIds = append(params.ClaimIds, c.ClaimID)
		}

		claimsInfo, err = s.lastmileomsClient.ClaimsInfo(gCtx, params)
		if err != nil {
			s.logger.Error(
				"failed to get info in last mile OMS",
				zap.Error(err),
			)

			switch {
			case errors.Is(err, http.ErrBadRequest):
				return errors.Join(err, service.ErrBadRequest)

			default:
				return fmt.Errorf("s.lastmileomsClient.ClaimsInfo: %w", err)
			}
		}

		return nil
	})

	var claimsCount int

	g.Go(func() error {
		cnt, err := s.repo.GetUserClaimsCount(gCtx, params.UserID)
		if err != nil {
			return fmt.Errorf("s.repo.GetUserClaimsCount: %w", err)
		}

		claimsCount = cnt

		return nil
	})

	if err := g.Wait(); err != nil {
		return dto.ClaimsInfo{}, err //nolint:wrapcheck
	}

	return dto.ClaimsInfo{
		Claims:     claimsInfo,
		TotalCount: claimsCount,
	}, nil
}

