func (r *Repository) GetUserClaimByClaimIDs(ctx context.Context, claimIDs []uuid.UUID, userID string) ([]claim.Claim, error) {
	ctx, span := tracing.Start(ctx, "database:GetUserClaimByClaimIDs")
	defer span.End()

	params := queries.GetUserClaimByClaimIDsParams{
		ClaimIds: nil,
		UserID:   userID,
	}

	for _, c := range claimIDs {
		params.ClaimIds = append(params.ClaimIds, c.String())
	}

	rows, err := r.slave.GetUserClaimByClaimIDs(ctx, params)

	if len(rows) == 0 {
		return nil, ErrClaimNotFound
	}

	if err != nil {
		switch {
		case errors.Is(err, pgx.ErrNoRows):
			return nil, ErrClaimNotFound

		default:
			return nil, fmt.Errorf("r.slave.GetUserClaimByClaimIDs: %w", err)
		}
	}

	out := make([]claim.Claim, len(rows))

	for i, r := range rows {
		c, err := toClaimPaymentDomainModel(&r.Claim, &r.Claimpayment)
		if err != nil {
			return nil, fmt.Errorf("toClaimPaymentDomainModel: %w", err)
		}

		out[i] = c
	}

	return out, nil
}

