func toClaimPaymentDomainModel(c *queries.Claim, p *queries.Claimpayment) (claim.Claim, error) {
	var deletedAt *time.Time
	if c.DeletedAt.Valid {
		deletedAt = &c.DeletedAt.Time
	}

	var state claim.State

	err := json.Unmarshal(c.State, &state)
	if err != nil {
		return claim.Claim{}, fmt.Errorf("json.Unmarhsal: %w", err)
	}

	out := claim.Claim{
		ClaimID:         c.ClaimID,
		Tariff:          claim.Tariff(c.Tariff),
		Email:           c.Email,
		UserID:          c.UserID,
		ExternalOrderID: c.ExternalOrderID,
		State:           state,
		Payment:         nil,
		CreatedAt:       c.CreatedAt.Time,
		UpdatedAt:       c.UpdatedAt.Time,
		DeletedAt:       deletedAt,
	}

	if p.CreatedAt.Valid {
		out.Payment = &domain.Payment{
			PaymentID:       int(*p.PaymentID),
			ClaimID:         c.ClaimID,
			OrderID:         c.ExternalOrderID,
			RefundID:        p.RefundID,
			Status:          string(p.Status.PaymentStateEnum),
			PaymentMethodID: *p.PaymentMethodID,
			Client:          int(*p.Client),
			TotalCost:       *p.TotalCost,
			DeliveryCost:    *p.DeliveryCost,
			CourierCost:     *p.CourierCost,
			FinalCost:       *p.FinalCost,
			CreatedAt:       p.CreatedAt.Time,
			UpdatedAt:       p.UpdatedAt.Time,
		}
	}

	return out, nil
}

func (c *Client) ClaimsInfo(
	ctx context.Context,
	params *dto.ClaimsInfoParams,
) ([]dto.Claim, error) {
	ctx, span := tracing.Start(ctx, "lastmileoms:ClaimsInfo")
	defer span.End()

	lmParams := toHTTPClaimsListParams(params)
	lmParams.PartnerIds = &[]string{
		c.tariffQuickPartnerID.Default,
		c.tariffQuickPartnerID.NewUser,
		c.tariffFourHoursPartnerID.Default,
		c.tariffFourHoursPartnerID.NewUser,
	}

	lmParams.Expand = &[]string{
		string(lastmileomshttpclient.ClaimsInfoParamsExpandBillingDetails),
		string(lastmileomshttpclient.ClaimsInfoParamsExpandPartnerId),
	}

	log := c.logger.With(
		zap.String("http_client", "lm_oms"),
		zap.String("method", "claims_list"),
	)

	resp, err := c.client.ClaimsListWithResponse(
		ctx,
		lmParams,
	)
	if err != nil {
		return nil, fmt.Errorf("c.client.ClaimsListWithResponse: %w", err)
	}

	switch resp.StatusCode() {
	case http.StatusOK:
		return toDtoClaims(resp.JSON200.Claims, c.tariffQuickPartnerID, c.tariffFourHoursPartnerID)

	case http.StatusBadRequest:
		log.Error(
			"response code 400",
			zap.Any("details", helpers.Deref(resp.JSON400.Details)),
		)

		return nil, fmt.Errorf("%w: %s", infra.ErrBadRequest, helpers.Deref(resp.JSON400.Details))

	default:
		log.Error(
			"unhandled status code",
			zap.Int("status_code", resp.StatusCode()),
		)

		return nil, fmt.Errorf("unhandled status code: %d", resp.StatusCode())
	}
}

