func (c *ClientWithResponses) ClaimsListWithResponse(ctx context.Context, params *ClaimsListParams, reqEditors ...RequestEditorFn) (*ClaimsListResponse, error) {
	rsp, err := c.ClaimsList(ctx, params, reqEditors...)
	if err != nil {
		return nil, err
	}
	return ParseClaimsListResponse(rsp)
