				ArrivalCost: &c.Estimation.BillingDetails.Arrival,
				RouteCost:   &c.Estimation.BillingDetails.Route,
				WaitCost:    &c.Estimation.BillingDetails.Wait,
				WeightCost:  &c.Estimation.BillingDetails.Weight,
			},
		}
	}

	var itemsInfo []serverhttp.ItemInfo

	if c.Items.ItemsInfo != nil {
		for _, item := range c.Items.ItemsInfo {
			itemsInfo = append(itemsInfo, serverhttp.ItemInfo{
				Depth:  item.Depth,
				Height: item.Height,
				Name:   item.Name,
				Price:  item.Price,
				Width:  item.Width,
			})
		}
	}

	var cancelReason *serverhttp.CancelReason
	if c.State.CancelReason != nil {
		cancelReason = &serverhttp.CancelReason{
			Code:    c.State.CancelReason.Code,
			Message: c.State.CancelReason.Message,
		}
	}

	src := c.RoutePoints[0]
	dst := c.RoutePoints[1]

	return serverhttp.Claim{
		ClaimId:         &c.ClaimID,
		Comment:         c.Comment,
		CourierInfo:     courierInfo,
		CreatedAt:       c.CreatedAt,
		DueTime:         c.DueTime,
		Estimation:      estimation,
		ExternalOrderId: &c.ExternalOrderId,
		Items: serverhttp.Items{
			Cost:      c.Items.Cost,
			Weight:    c.Items.Weight,
			ItemsInfo: &itemsInfo,
		},
		Meta:            nil,
		NeedDropOffCode: &c.NeedDropOffCode,
		NeedReturn:      &c.NeedReturn,
		RoutePoints: []serverhttp.RoutePoint{
			{
				Address: serverhttp.Address{
					Comment: src.Address.Comment,
					Coordinates: serverhttp.Coordinates{
						Lat: src.Address.Coordinates.Lat,
						Lon: src.Address.Coordinates.Lon,
					},
					DoorCode: src.Address.DoorCode,
					Flat:     src.Address.Flat,
					Floor:    src.Address.Floor,
					FullName: src.Address.FullName,
					Porch:    src.Address.Porch,
				},
				Contact: serverhttp.Contact{
					ExtensionNumber: src.Contact.ExtensionNumber,
					ExtraPhone:      src.Contact.ExtraPhone,
					Name:            src.Contact.Name,
					Phone:           src.Contact.Phone,
				},
				PointType:    serverhttp.RoutePointType(src.Type),
				TransferCode: nil,
			},
			{
				Address: serverhttp.Address{
					Comment: dst.Address.Comment,
					Coordinates: serverhttp.Coordinates{
						Lat: dst.Address.Coordinates.Lat,
						Lon: dst.Address.Coordinates.Lon,
					},
					DoorCode: dst.Address.DoorCode,
					Flat:     dst.Address.Flat,
					Floor:    dst.Address.Floor,
					FullName: dst.Address.FullName,
					Porch:    dst.Address.Porch,
				},
				Contact: serverhttp.Contact{
					ExtensionNumber: dst.Contact.ExtensionNumber,
					ExtraPhone:      dst.Contact.ExtraPhone,
					Name:            dst.Contact.Name,
					Phone:           dst.Contact.Phone,
				},
				PointType:    serverhttp.RoutePointType(dst.Type),
				TransferCode: nil,
			},
		},
		State: &serverhttp.ClaimState{
			CancelReason: cancelReason,
			Status:       serverhttp.ClaimStatus(c.State.Status),
		},
		Tariff: serverhttp.Tariff(c.Tariff),
	}
