func (s *Service) ClaimInfo(ctx context.Context, claimID uuid.UUID, userID *string) (dto.Claim, error) {
	ctx, span := tracing.Start(ctx, "claim:ClaimInfo")
	defer span.End()

	span.SetAttributes(
		attribute.Stringer("claim_id", claimID),
	)

	var (
		c   *domainClaim.Claim
		err error
	)

	if userID != nil {
		c, err = s.repo.GetUserClaimByClaimID(ctx, claimID, *userID)
	} else {
		c, err = s.repo.GetClaimByClaimID(ctx, claimID)
	}

	if err != nil {
		s.logger.Error("failed to check claims", zap.Error(err))

		switch {
		case errors.Is(err, claim.ErrClaimNotFound):
			return dto.Claim{}, service.ErrClaimNotFound

		default:
			return dto.Claim{}, fmt.Errorf("s.repo.GetUserClaimByClaimID: %w", err)
		}
	}

	info, err := s.lastmileomsClient.C2CClaimInfo(ctx, c.ClaimID, dto.Tariff(c.Tariff))
	if err != nil {
		s.logger.Error(
			"failed to get info in last mile OMS",
			zap.Error(err),
		)

		switch {
		case errors.Is(err, http.ErrBadRequest):
			return dto.Claim{}, errors.Join(err, service.ErrBadRequest)

		default:
			return dto.Claim{}, fmt.Errorf("s.lastmileomsClient.ClaimInfo: %w", err)
		}
	}

	return info, nil
}

