func (h *Handlers) ClaimStatus(
	c echo.Context,
	claimID serverhttp.ClaimID,
	params serverhttp.ClaimStatusParams,
) error {
	cl, err := h.S.ClaimService.GetUserClaimByClaimID(c.Request().Context(), params.XUserID, claimID)
