func (s *Service) GetShippings(ctx context.Context, params dto.GetShippingParams) ([]dto.TrackingData, error) {
	trackLinks, err := s.repository.TrackingLink.GetTrackingLinksByMagnitID(ctx, params)
	if err != nil {
		if errors.Is(err, tracking_link.ErrTrackingLinkNotFound) {
			return nil, ErrShippingsNotFound
		}

		return nil, fmt.Errorf("s.repository.TrackingLink.GetTrackingLinksByMagnitID: %w", err)
	}

	// мапа для восстановления порядка сообщений
	indexes := make(map[string]int, len(trackLinks))

	postOrders := make([]*dto.TrackingLink, 0, len(trackLinks))
	lmOrders := make([]*dto.TrackingLink, 0, len(trackLinks))
	c2cOrders := make([]*dto.TrackingLink, 0, len(trackLinks))

	for i, link := range trackLinks {
		indexes[link.ClaimID.String()] = i

		switch link.Source {
		case dto.TrackingLinkSourceUnspecified:
			continue

		case dto.TrackingLinkSourceOMS:
			lmOrders = append(lmOrders, link)

		case dto.TrackingLinkSourceC2C:
			c2cOrders = append(c2cOrders, link)

		case dto.TrackingLinkSourcePost:
			postOrders = append(postOrders, link)
		}
	}

	g, gCtx := errgroup.WithContext(ctx)

	var (
		lmData   []dto.TrackingData
		c2cData  []dto.TrackingData
		postData []dto.TrackingData
	)

	g.Go(func() error {
		var gErr error
		if lmData, gErr = getData(gCtx, lmOrders, s.lastMileOMSClient.ClaimsList); gErr != nil {
			return gErr
		}

		return nil
	})

	g.Go(func() error {
		var gErr error
		if c2cData, gErr = getData(gCtx, c2cOrders, s.lastMileOMSClient.ClaimsList); gErr != nil {
			return gErr
		}

		return nil
	})

	g.Go(func() error {
		var gErr error
		if postData, gErr = getData(gCtx, postOrders, s.magnitPostClient.GetOrdersInfoByIdsV2); gErr != nil {
			return gErr
		}

		return nil
	})

	if gErr := g.Wait(); gErr != nil {
		return nil, fmt.Errorf("failed to fetch data: %w", gErr)
	}

	data := restoreOrder(
		indexes,
		lmData,
		c2cData,
		postData,
	)

	// проставляем partnerDisplayName и Source
	for i, d := range data {
		data[i].Source = trackLinks[i].Source

		partnerDisplayName := trackLinks[i].DisplayName

		if d.LastMileTrackingData != nil && partnerDisplayName != nil {
			d.LastMileTrackingData.PartnerDisplayName = *partnerDisplayName
		}

		if d.MagnitPostTrackingData != nil && partnerDisplayName != nil {
			if d.MagnitPostTrackingData.OrderInfoV2.TrackingNumber != "" {
				d.MagnitPostTrackingData.OrderInfoV2.PartnerDisplayName = *partnerDisplayName
			}

			if d.MagnitPostTrackingData.OrderInfo.TrackingNumber != "" {
				d.MagnitPostTrackingData.OrderInfo.PartnerDisplayName = *partnerDisplayName
			}
		}
	}

	return data, nil
}

func (r *Repository) GetTrackingLinksByMagnitID(
	ctx context.Context,
	params dto.GetShippingParams,
