		arg.MagnitID,
		arg.SortDirection,
		arg.Offset,
		arg.Limit,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []TrackingLink
	for rows.Next() {
		var i TrackingLink
		if err := rows.Scan(
			&i.ClaimID,
			&i.Source,
			&i.CreatedAt,
			&i.ExpiresAt,
			&i.MagnitID,
			&i.UserPhone,
			&i.PartnerID,
			&i.PartnerDisplayName,
			&i.ShortID,
			&i.UpdatedAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

