func toOrderV2Dto(order *postGRPC.OrderV2) dto.PostOrderInfoV2 {
	parcels := make([]dto.PostParcelInfo, 0, len(order.GetParcels()))

	for _, p := range order.GetParcels() {
		var storageEndDate *time.Time
		if p.StorageEndDate != nil {
			storageEndDate = helpers.Ptr(p.StorageEndDate.AsTime())
		}

		parcels = append(parcels, dto.PostParcelInfo{
			ParcelID:       p.Id,
			Barcode:        p.Barcode,
			Status:         toOrderStatusDto(p.GetStatus()),
			DeclaredValue:  p.Payment.DeclaredValue,
			Weight:         int(p.Characteristic.Weight),
			Length:         int(p.Characteristic.Length),
			Width:          int(p.Characteristic.Width),
			Height:         int(p.Characteristic.Height),
			StorageEndDate: storageEndDate,
		})
	}

	createdAt := helpers.Ptr(order.GetCreatedAt().AsTime())

	var recipient *dto.PostOrderRecipient

	if order.GetDelivery().Recipient != nil {
		rcp := order.GetDelivery().GetRecipient()

		recipient = &dto.PostOrderRecipient{
			FirstName:   rcp.GetFirstName(),
			LastName:    rcp.GetFamilyName(),
			PhoneNumber: rcp.GetPhoneNumber(),
			Address:     rcp.Address,
		}
	}

	return dto.PostOrderInfoV2{
		TrackingNumber:     order.GetTrackingNumber(),
		CustomerOrderID:    order.GetCustomerOrderId(),
		ExternalOrderID:    helpers.Ptr(order.GetExternalOrderId()),
		ShortID:            helpers.ShortID(order.GetTrackingNumber()),
		PartnerDisplayName: "", // заполняется потом в сервисе
		IssueCode:          helpers.Ptr(order.GetPickupCode()),
		WarehouseID:        helpers.Ptr(order.GetWarehouseId()),
		Delivery: dto.PostOrderDelivery{
			PickupPointKey:     order.GetDelivery().GetPickupPointKey(),
			PickupPointAddress: order.GetDelivery().GetPickupPointAddress(),
			Recipient:          recipient,
		},
		Parcels:   parcels,
		CreatedAt: createdAt,
	}
}

