func (h *Handlers) GetTrackingData(
	c echo.Context,
	trackID string,
	params serverhttp.GetTrackingDataParams,
) error {
	data, err := h.S.TrackingLinkService.TrackInfo(c.Request().Context(), trackID)

	switch {
	case errors.Is(err, service.ErrClaimNotFound):
		err = c.JSON(http.StatusNotFound, serverhttp.ResponseNotFound{
			Code:    serverhttp.NOTFOUND,
			Details: &[]string{"claim not found"},
		})

	case errors.Is(err, service.ErrTrackingLinkNotFound):
		err = c.JSON(http.StatusNotFound, serverhttp.ResponseNotFound{
			Code:    serverhttp.NOTFOUND,
			Details: &[]string{"tracking link not found"},
		})

	case errors.Is(err, service.ErrBadRequest):
	case errors.Is(err, nil):
		var resp serverhttp.ResponseGetTrackingData

		resp.Source = serverhttp.TrackSource(data.Source)

		// пользователь либо не авторизован,
		// либо у ссылки в базе не привязан конкретный пользователь,
		// либо пользователь А пытается посмотреть посылку пользователя Б
		// тогда мы покажем анонимку
		shortInfo := params.XUserID == nil || data.MagnitID == nil || *params.XUserID != *data.MagnitID

		switch data.Source {
		case dto.TrackingLinkSourceC2C, dto.TrackingLinkSourceOMS:
			err = fillLastMileTrackingData(&resp, data.LastMileTrackingData, shortInfo)

		case dto.TrackingLinkSourcePost:
			err = fillMagnitPostData(&resp, data.MagnitPostTrackingData, shortInfo)
			if errors.Is(err, ErrV1NotSupported) {
				return c.JSON(http.StatusBadRequest, serverhttp.ResponseNotFound{ //nolint:wrapcheck
					Code:    serverhttp.INVALIDSTATE,
					Details: &[]string{err.Error()},
				})
			}

		case dto.TrackingLinkSourceUnspecified:
			err = errors.New("tracking link not found")
		}

		if err == nil {
			err = c.JSON(http.StatusOK, resp)
		}
	default:
		l := logger.FromEchoContext(c).
			With(zap.String("source", string(data.Source))).
			With(zap.String("id", trackID)).
			With(zap.Error(err))

		l.Error("failed to get tracking data")

		err = c.JSON(http.StatusInternalServerError, "")
	}

	if err != nil {
		return fmt.Errorf("c.JSON: %w", err)
	}

	return nil
}

