func (h *Handlers) GetUserShippingsV2(c echo.Context, params serverhttp.GetUserShippingsV2Params) error {
	if err := c.Bind(&params); err != nil {
		err = c.JSON(http.StatusBadRequest, serverhttp.ResponseBadRequest{
			Code:    serverhttp.INVALIDSCHEMA,
			Details: helpers.Ptr([]string{err.Error()}),
		})
		if err != nil {
			return fmt.Errorf("ctx.JSON: %w", err)
		}

		return nil
	}

	if err := validate.V().StructCtx(c.Request().Context(), params); err != nil {
		err = c.JSON(http.StatusBadRequest, serverhttp.ResponseBadRequest{
			Code:    serverhttp.INVALIDSCHEMA,
			Details: helpers.Ptr([]string{err.Error()}),
		})
		if err != nil {
			return fmt.Errorf("ctx.JSON: %w", err)
		}

		return nil
	}

	pageSize := hardLimitV2
	if params.PageSize != nil && *params.PageSize > 0 {
		pageSize = *params.PageSize
	}

	if pageSize > hardLimitV2 {
		pageSize = hardLimitV2
	}

	page := 1
	if params.Page != nil && *params.Page > 0 {
		page = *params.Page
	}

	sortDirection := dto.SortDirectionDesc
	if params.OrderDirection != nil && string(*params.OrderDirection) == string(serverhttp.QueryOrderDirectionAcs) {
		sortDirection = dto.SortDirectionAsc
	}

	data, err := h.S.TrackingLinkService.GetShippings(c.Request().Context(), dto.GetShippingParams{
		MagnitID:      params.XUserId,
		Page:          page,
		PageSize:      pageSize,
		SortDirection: sortDirection,
	})

	l := logger.FromContext(c.Request().Context()).With(zap.String("magnit_id", params.XUserId))

	if err != nil {
		if errors.Is(err, trackingLink.ErrShippingsNotFound) {
			return c.JSON(http.StatusNotFound, serverhttp.ResponseNotFound{ //nolint:wrapcheck
				Code:    serverhttp.NOTFOUND,
				Details: &[]string{"no shippings found"},
			})
		}

		l.Error("failed to get user shippings", zap.Error(err))

		return c.JSON(http.StatusInternalServerError, nil) //nolint:wrapcheck
	}

	var resp serverhttp.ResponseGetShippingsV2

	for _, shipping := range data {
		var trackingData serverhttp.ResponseGetTrackingDataV2

		trackingData.Source = serverhttp.TrackSource(shipping.Source)

		switch shipping.Source {
		case dto.TrackingLinkSourceC2C, dto.TrackingLinkSourceOMS:
			err = fillLastMileTrackingDataV2(&trackingData, shipping.LastMileTrackingData, false)

		case dto.TrackingLinkSourcePost:
			err = fillMagnitPostDataV2(&trackingData, shipping.MagnitPostTrackingData, false)

		case dto.TrackingLinkSourceUnspecified:
			err = errors.New("tracking link not found")
		}

		if err != nil {
			l.Error("failed to transform user shippings into http response V2", zap.Error(err))

			continue
		}

		resp = append(resp, trackingData)
	}

	return c.JSON(http.StatusOK, resp) //nolint:wrapcheck
}

