func (s *Service) TrackInfo(ctx context.Context, trackID string) (dto.TrackingData, error) {
	trackLink, err := s.repository.TrackingLink.GetTrackingDataByTrackID(ctx, trackID)
	if err != nil {
		if errors.Is(err, trackingLinkRepo.ErrTrackingLinkNotFound) {
			return dto.TrackingData{}, service.ErrTrackingLinkNotFound
		}

		return dto.TrackingData{}, fmt.Errorf("repository.TrackingLink.GetTrackingDataByTrackID: %w", err)
	}

	claimID := trackLink.ClaimID

	var partnerDisplayName string
	if trackLink.DisplayName != nil {
		partnerDisplayName = *trackLink.DisplayName
	}

	out := dto.TrackingData{
		Source:                 trackLink.Source,
		MagnitID:               trackLink.MagnitID,
		LastMileTrackingData:   nil,
		MagnitPostTrackingData: nil,
	}

	if trackLink.Source == dto.TrackingLinkSourceC2C || trackLink.Source == dto.TrackingLinkSourceOMS {
		claim, err := s.lastMileOMSClient.ClaimInfo(ctx, claimID, trackLink.PartnerID.String())
		if err != nil {
			if errors.Is(err, service.ErrClaimNotFound) {
				return dto.TrackingData{}, service.ErrClaimNotFound
			}

			return dto.TrackingData{}, fmt.Errorf("s.lastMileOMSClient.ClaimInfo: %w", err)
		}

		lmData, err := infoToLastMileTrackingData(claim)
		if err != nil {
			return dto.TrackingData{}, fmt.Errorf("infoToLastMileTrackingData: %w", err)
		}

		lmData.PartnerDisplayName = partnerDisplayName
		lmData.ShortID = helpers.ShortID(lmData.ClaimID.String())

		out.LastMileTrackingData = &lmData
	}

	if trackLink.Source == dto.TrackingLinkSourcePost {
		postDataV2, err := s.magnitPostClient.GetPartnerOrderInfoByIDV2(ctx, claimID, trackLink.PartnerID)
		if err != nil {
			return dto.TrackingData{}, fmt.Errorf(
				"s.magnitPostClient.GetPartnerOrderInfoByID: %s: %w",
				claimID.String(),
				err,
			)
		}

		postDataV2.PartnerDisplayName = partnerDisplayName
		postDataV2.ShortID = helpers.ShortID(claimID.String())

		pupInfo, err := s.magnitPostClient.GetPickupPointByKey(ctx, postDataV2.Delivery.PickupPointKey)
		if err != nil {
			return dto.TrackingData{}, fmt.Errorf(
				"magnitPostClient.GetPickupPointByKey: %s: %w",
				postDataV2.Delivery.PickupPointKey,
				err,
			)
		}

		// v2
		out.MagnitPostTrackingData = &dto.PostTrackingData{ //nolint:exhaustruct
			OrderInfoV2: postDataV2,
			Pup:         pupInfo,
		}

		// v1 только если 1 посылка
		if len(postDataV2.Parcels) == 1 {
			out.MagnitPostTrackingData.OrderInfo = mapV2ToV1(postDataV2)
		} else {
			// v1 не поддерживает многоместные заказы — сигнализируем флагом
			out.MagnitPostTrackingData.V1NotSupported = true
		}
	}

	return out, nil
}

func (r *Repository) GetTrackingDataByTrackID(ctx context.Context, trackID string) (*dto.TrackingLink, error) {
	var (
		trackingLink queries.TrackingLink
		err          error
	)

	if claimID, parseErr := uuid.Parse(trackID); parseErr == nil {
		trackingLink, err = r.slave.GetTrackingDataByClaimID(ctx, claimID)
	} else {
		trackingLink, err = r.slave.GetTrackingDataByShortID(ctx, trackID)
	}

	if err != nil {
		if errors.Is(err, sql.ErrNoRows) {
			return nil, ErrTrackingLinkNotFound
		}

		return nil, fmt.Errorf("repository.GetTrackingDataByTrackID: %w", err)
	}

	return LinkToDomain(&trackingLink), nil
}

