func (c *Client) GetPickupPointByKey(ctx context.Context, key string) (dto.PickupPoint, error) {
	resp, err := c.client.MagnitPostService.GetPickupPointByKey(ctx, &postGRPC.GetPickupPointByKeyRequest{
		PupKey: key,
	})
	if err != nil {
		if postGRPC.IsErr(err, postGRPC.GetPickupPointByKeyReply_NOT_FOUND) {
			return dto.PickupPoint{}, ErrPickupPointNotFound
		}

		return dto.PickupPoint{}, fmt.Errorf("c.client.MagnitPostService.GetPickupPointByKey: %w", err)
	}

	pup := resp.GetPup()

	wh := make([]dto.WorkHours, 0)

	for _, w := range pup.GetWorkHours() {
		wh = append(wh, dto.WorkHours{
			Weekday: toWeekDay(w.GetDay()),
			From:    w.GetFrom(),
			Till:    w.GetTill(),
		})
	}

	return dto.PickupPoint{
		Key:       pup.Key,
		Name:      pup.Name,
		Type:      toPickupPointType(pup.Type),
		Address:   pup.Address,
		Region:    pup.Region,
		City:      pup.City,
		Index:     pup.Index,
		WorkHours: wh,
	}, nil
}

