func (d *Consumer) HandleMessage(
	ctx context.Context,
	msg *lastmileomsGen.LastmileOmsClaimEventV1Message,
) error {
	if msg == nil || msg.Value == nil {
		return nil
	}

	msgValue := msg.Value

	if msgValue.Status == nil {
		return fmt.Errorf("event status is nil")
	}

	var claimID uuid.UUID
	if err := claimID.Scan(msg.Value.ClaimId); err != nil {
		return nil //nolint:nilerr
	}

	var (
		status       domainClaim.Status
		cancelReason *domainClaim.CancelReason
	)

	if msgValue.GetStatus() == nil {
		d.logger.Warn("no status for claim", zap.String("claim_id", claimID.String()))

		return nil
	}

	status = domainClaim.Status(msgValue.GetStatus().Status)

	if cr := msgValue.Status.GetCancelReason(); cr != nil {
		cancelReason = &domainClaim.CancelReason{
			Code:    domainClaim.CancelCode(cr.GetCode()),
			Message: nil,
		}

		if cr.Message != "" {
			cancelReason.Message = helpers.Ptr(domainClaim.CancelMessage(cr.Message))
		}
	}

	eventTime := time.Now()

	if msgValue.Timestamp != nil {
		eventTime = msgValue.Timestamp.AsTime()
	}

	claim, err := d.claimSvc.UpdateClaimStatus(ctx, &dto.UpdateClaimStatusParams{
		ClaimID:      claimID,
		Status:       status,
		CancelReason: cancelReason,
		UpdatedAt:    eventTime,
	})
	if err != nil {
		switch {
		case errors.Is(err, service.ErrClaimNotFound):
			d.logger.Debug(
				"unknown claim",
				zap.String("claim_id", claimID.String()),
			)

		default:
			d.logger.Error(
				"failed to update claim",
				zap.String("claim_id", claimID.String()),
				zap.Error(err),
			)
		}

		return nil
	}

	d.metrics.AddClaimStatus(ctx, msgValue.GetStatus().Status)

	//nolint:exhaustive
	switch status {
	case domainClaim.StatusDeliveryFinished,
		domainClaim.StatusReturnFinished,
		domainClaim.StatusReturnFailed:
		err = d.paymentSvc.DepositAll(ctx, &claim)
		if err != nil {
			d.logger.Error(
				"failed to deposit claim",
				zap.String("claim_id", claimID.String()),
				zap.Error(err),
			)
		}

	case domainClaim.StatusCancelledByService, domainClaim.StatusCancelled:
		err = d.paymentSvc.CancelPayment(ctx, claimID)
		if err != nil {
			d.logger.Error(
				"failed to cancel payment",
				zap.String("claim_id", claimID.String()),
				zap.Error(err),
			)
		}

	case domainClaim.StatusCancelledWithPayment:
		err = d.paymentSvc.DepositAll(ctx, &claim)
		if err != nil {
			d.logger.Error(
				"failed to deposit claim",
				zap.String("claim_id", claimID.String()),
				zap.Error(err),
			)
		}

	case domainClaim.StatusPickedUp:
		err = d.smsSvc.CourierSoonArrivalSMS(ctx, claim.UserID, claimID)
		if err != nil {
			d.logger.Error(
				"failed to send sms",
				zap.String("claim_id", claimID.String()),
				zap.Error(err),
			)
		}
	}

	return nil
}

