func (s *Service) UpdateClaimStatus(
	ctx context.Context,
	params *dto.UpdateClaimStatusParams,
) (claim.Claim, error) {
	ctx, span := tracing.Start(ctx, "claim:UpdateClaimStatus")
	defer span.End()

	span.SetAttributes(
		attribute.Stringer("claim_id", params.ClaimID),
	)

	cl, err := s.repo.GetClaimByClaimID(ctx, params.ClaimID)
	if err != nil {
		switch {
		case errors.Is(err, pgx.ErrNoRows):
			return claim.Claim{}, service.ErrClaimNotFound

		default:
			s.logger.Error(
				"failed to get claim",
				zap.String("claim_id", params.ClaimID.String()),
				zap.Error(err),
			)

			return claim.Claim{}, fmt.Errorf("c.repo.GetClaimByID: %w", err)
		}
	}

	if !params.UpdatedAt.After(cl.UpdatedAt) {
		return *cl, nil
	}

	cl.State.Status = params.Status
	cl.UpdatedAt = params.UpdatedAt

	if params.CancelReason != nil {
		cl.State.CancelReason = params.CancelReason
	}

	updatedClaim, err := s.repo.Save(ctx, cl)
	if err != nil {
		s.logger.Error(
			"failed to save claim",
			zap.String("claim_id", params.ClaimID.String()),
			zap.Error(err),
		)

		return claim.Claim{}, fmt.Errorf("c.repo.Save: %w", err)
	}

	s.logger.Info(
		"claim updated",
		zap.String("claim_id", params.ClaimID.String()),
		zap.Any("claim_state", cl.State),
	)

	return updatedClaim, nil
}

