	claimState := state{
		Status:       string(d.State.Status),
		CancelReason: nil,
	}

	if d.State.CancelReason != nil {
		claimState.CancelReason = &cancelReason{
			Code:    string(d.State.CancelReason.Code),
			Message: nil,
		}

		if d.State.CancelReason.Message != nil {
			claimState.CancelReason.Message = helpers.Ptr(string(*d.State.CancelReason.Message))
		}
	}

	b, err := json.Marshal(claimState)
	if err != nil {
		return nil, fmt.Errorf("json.Marshal: %w", err)
	}

	createdAt := pgtype.Timestamptz{
		Time:             d.CreatedAt,
		Valid:            true,
		InfinityModifier: pgtype.Finite,
	}

	updatedAt := pgtype.Timestamptz{
		Time:             d.UpdatedAt,
		Valid:            true,
		InfinityModifier: pgtype.Finite,
	}

	deletedAt := pgtype.Timestamptz{
		Time:             time.Time{},
		Valid:            false,
		InfinityModifier: pgtype.Finite,
	}

	if d.DeletedAt != nil {
		deletedAt.Time = *d.DeletedAt
		deletedAt.Valid = true
	}

	return &queries.Claim{
		ClaimID:         d.ClaimID,
		Tariff:          queries.TariffEnum(d.Tariff),
		Email:           d.Email,
		ExternalOrderID: d.ExternalOrderID,
		UserID:          d.UserID,
		State:           b,
		CreatedAt:       createdAt,
		UpdatedAt:       updatedAt,
		DeletedAt:       deletedAt,
	}, nil
}

