func (s *Service) DepositAll(ctx context.Context, claim *domainClaim.Claim) error {
	ctx, span := tracing.Start(ctx, "payment:DepositAll")
	defer span.End()

	span.SetAttributes(
		attribute.Stringer("claim_id", claim.ClaimID),
	)

	if claim.Payment == nil || claim.Payment.CreatedAt.IsZero() {
		return errors.New("no payment for claim")
	}

	if claim.State.Status != domainClaim.StatusDeliveryFinished &&
		claim.State.Status != domainClaim.StatusReturnFinished &&
		claim.State.Status != domainClaim.StatusReturnFailed &&
		claim.State.Status != domainClaim.StatusCancelledWithPayment {
		return fmt.Errorf("claim is in wrong status for deposit: %s", claim.State.Status)
	}

	payment := claim.Payment

	_, err := s.paymentProcessor.Deposit(ctx, &dto.DepositParams{
		OrderId:  payment.OrderID,
		Client:   payment.Client,
		TotalSum: payment.TotalCost,
		Services: dto.PaymentServices{
			Delivery: &dto.PaymentServiceDelivery{
				Price: dto.PaymentPrice{
					Value: uint64(payment.DeliveryCost), //nolint:gosec
				},
			},
			Courier: &dto.PaymentServiceCourier{
				Price: dto.PaymentPrice{
					Value: uint64(payment.CourierCost), //nolint:gosec
				},
			},
		},
	})
	if err != nil {
		s.logger.Error(
			"failed to deposit money",
			zap.String("claim_id", claim.ClaimID.String()),
			zap.Error(err),
		)

		return fmt.Errorf("s.paymentProcessor.CreatePayment: %w", err)
	}

	payment.Status = string(domain.PaymentStatusToDeposit)

	_, err = s.paymentRepo.Save(ctx, payment)
	if err != nil {
		s.logger.Error(
			"failed to save payment",
			zap.String("claim_id", claim.ClaimID.String()),
			zap.Error(err),
		)

		return fmt.Errorf("s.paymentRepo.Save: %w", err)
	}

	s.logger.Info(
		"successful grpc call to deposit money for: arrival, delivery",
		zap.String("claim_id", claim.ClaimID.String()),
		zap.String("external_order_id", payment.OrderID),
	)

	return nil
}

