	_, err = s.paymentProcessor.CancelPayment(ctx, payment.OrderID)
	if err != nil {
		s.logger.Error(
			"failed to cancel claim in payment processing service",
			zap.String("claim_id", claimID.String()),
			zap.Error(err),
		)

		return fmt.Errorf("s.paymentProcessor.CancelPayment: %w", err)
	}

	payment.Status = string(domain.PaymentStatusToCancel)

	payment, err = s.paymentRepo.Save(ctx, payment)
	if err != nil {
		s.logger.Error(
			"failed to save payment",
			zap.String("claim_id", claimID.String()),
			zap.Error(err),
		)

		return fmt.Errorf("s.paymentRepo.Save: %w", err)
	}

	s.logger.Info(
		"successfullful grpc call to cancel payment",
		zap.String("claim_id", claimID.String()),
		zap.String("external_order_id", payment.OrderID),
	)

	return nil
}

