func (s *Service) CourierSoonArrivalSMS(ctx context.Context, userID string, claimID uuid.UUID) error {
	ctx, span := tracing.Start(ctx, "SMSService:CourierSoonArrivalSMS")
	defer span.End()

	span.SetAttributes(
		attribute.Stringer("claim_id", claimID),
		attribute.String("user_id", userID),
	)

	claimInfo, err := s.lastMileOMSClient.ClaimsInfo(ctx, &dto.ClaimsInfoParams{ //nolint:exhaustruct
		ClaimIds: []uuid.UUID{claimID},
		UserID:   userID,
	})
	if err != nil {
		s.logger.Error(
			"failed to get info in last mile OMS",
			zap.Error(err),
		)

		switch {
		case errors.Is(err, http.ErrBadRequest):
			return errors.Join(err, service.ErrBadRequest)

		default:
			return fmt.Errorf("s.lastmileomsClient.ClaimInfo: %w", err)
		}
	}

	if len(claimInfo) == 0 {
		return ErrClaimsNotFound
	}

	if claimInfo[0].CourierInfo == nil {
		return ErrEmptyCourierInfo
	}

	dropOffPointPhone := helpers.Deref(claimInfo[0].RoutePoints[1].Contact).Phone
	courierPhone := claimInfo[0].CourierInfo.Phone

	attempt := 0

	if err := retry.Do(func() error {
		attempt++
		s.logger.Info(
			"sending sms attempt",
			zap.String("claim_id", claimID.String()),
			zap.Int("attempt", attempt),
		)
		lmWebhooksErr := s.lastMileWebhooksClient.SendSMS(
			ctx, dropOffPointPhone, courierPhone)

		if errors.Is(lmWebhooksErr, http.ErrInternal) {
			return lmWebhooksErr //nolint:wrapcheck
		}

		return nil
	},
		retry.Attempts(3),
		retry.Delay(time.Second*5),
	); err != nil {
		s.logger.Error("failed to send sms", zap.Error(err))

		return fmt.Errorf("failed to send sms: %w", err)
	}

	s.logger.Info(
		"sms successfully sent",
		zap.String("claim_id", claimID.String()),
		zap.String("user_id", userID),
	)

	return nil
}

