func (c *Client) SendSMS(
	ctx context.Context,
	userPhone string,
	courierPhone string,
) error {
	req := &genGRPC.SendSMSRequest{
		Phone:   userPhone,
		SmsType: genGRPC.SMSType_COURIER_SOON_ARRIVAL,
		Payload: &genGRPC.SendSMSRequest_CourierSoonArrival{
