		zap.String("user_phone", userPhone),
		zap.String("courier_phone", courierPhone),
		zap.Any("sms_type", req.SmsType),
	)

	resp, err := c.client.LastMileWebhooksService.SendSMS(ctx, req)
	if err != nil {
		st, ok := status.FromError(err)
		if ok {
			c.logger.Error("gRPC SendSMS failed",
				zap.String("code", st.Code().String()),
				zap.String("message", st.Message()),
			)
		} else {
			c.logger.Error("SendSMS failed with unknown gRPC error", zap.Error(err))
		}

		return fmt.Errorf("c.client.LastMileWebhooksService.SendSMS: %w", err)
	}

	if resp.GetErrorReason() != genGRPC.SendSMSReply_ERR_INFO_REASON(0) {
		c.logger.Error("SendSMSReply contains error_reason",
			zap.String("error_reason", resp.GetErrorReason().String()),
		)

		return fmt.Errorf("webhooks error: %s", resp.GetErrorReason().String())
	}

	c.logger.Info("gRPC SendSMS succeeded")

	return nil
}

