func (d *Consumer) HandleMessage(
	ctx context.Context,
	msg *paymentGen.PaymentProcessingOrderPaymentEventV1Message,
) error {
	val := msg.Value

	var err error

	switch val.GetEvent() {
	case paymentGen.EventName_ORDER_PAYMENT_EVENT_UNSPECIFIED:
	case paymentGen.EventName_ORDER_PAYMENT_EVENT_TO_CREATED:
		err = d.controller.handleCreated(ctx, msg)

	case paymentGen.EventName_ORDER_PAYMENT_EVENT_TO_DEPOSITED:
		err = d.controller.handleDeposited(ctx, msg)

	case paymentGen.EventName_ORDER_PAYMENT_EVENT_TO_CANCELED:
		err = d.controller.handleCanceled(ctx, msg)

	case paymentGen.EventName_ORDER_PAYMENT_EVENT_TO_REFUNDED:
		err = d.controller.handleRefund(ctx, msg)

	default:
		return errors.New("unspecified event")
	}

	if err != nil {
		d.logger.Error("payment error", zap.Error(err))
	}

	return nil
}

