func (s *Service) UpdatePayment(ctx context.Context, params *dto.UpdatePaymentParams) (*domain.Payment, error) {
	ctx, span := tracing.Start(ctx, "payment:UpdatePayment")
	defer span.End()

	payment, err := s.paymentRepo.GetPaymentByOrderIDAndClient(ctx, &dto.GetDBPaymentParams{
		OrderID: params.OrderID,
		Client:  s.paymentProcessor.ClientID(),
	})
	if err != nil {
		s.logger.Error(
			"failed to get payment for by external order id",
			zap.String("external_order_id", params.OrderID),
			zap.Error(err),
		)

		return nil, fmt.Errorf("s.paymentRepo.GetPaymentByOrderIDAndClient: %w", err)
	}

	payment.Status = string(params.Status)

	switch params.Status { //nolint: exhaustive
	case dto.PaymentDeposited:
		payment.FinalCost = payment.TotalCost
	case dto.PaymentRefunded:
		payment.FinalCost = payment.CourierCost
	case dto.PaymentCanceled:
		payment.FinalCost = 0
	}

	if _, err := s.paymentRepo.Save(ctx, payment); err != nil {
		s.logger.Error(
			"failed to save payment",
			zap.String("claim_id", payment.ClaimID.String()),
			zap.String("external_order_id", payment.OrderID),
			zap.Error(err),
		)

		return nil, fmt.Errorf("s.paymentRepo.Save: %w", err)
	}

	s.logger.Info(
		"payment updated",
		zap.String("claim_id", payment.ClaimID.String()),
		zap.String("external_order_id", payment.OrderID),
		zap.Any("payment_status", payment.Status),
	)

	return payment, nil
}

