func (c *controller) handleDeposited(
	ctx context.Context,
	msg *paymentGen.PaymentProcessingOrderPaymentEventV1Message,
) error {
	event := msg.Value

	orderID := event.GetOrderId()

	if !strings.HasPrefix(orderID, config.OrderIDPrefix) {
		// не наш заказ
		return nil
	}

	if event.GetResult() != paymentGen.EventResult_ORDER_PAYMENT_TRANSITION_RESULT_SUCCESSFUL {
		return fmt.Errorf("failed to deposit money: %w", ErrTransitionFailed)
	}

	params := &dto.UpdatePaymentParams{
		OrderID: orderID,
		Status:  dto.PaymentDeposited,
	}

	_, err := c.paymentSvc.UpdatePayment(ctx, params)
	if err != nil {
		return fmt.Errorf("c.svc.UpdatePayment: %w", err)
	}

	claim, err := c.claimSvc.GetClaimByExternalOrderID(ctx, orderID)
	if err != nil {
		return fmt.Errorf("c.claimSvc.GetUserClaimByExternalOrderID: %w", err)
	}

	if claim.State.Status == domainClaim.StatusCancelledWithPayment {
		_, err = c.paymentSvc.RefundDeliveryService(ctx, claim.ClaimID)
		if err != nil {
			return fmt.Errorf("c.paymentSvc.RefundDeliveryService: %w", err)
		}
	}

	return nil
}

func (x *OrderPaymentEventV1) GetOrderId() string {
	if x != nil {
		return x.OrderId
	}
	return ""
}

func (x *OrderPaymentEventV1) GetResult() EventResult {
	if x != nil {
		return x.Result
	}
	return EventResult_ORDER_PAYMENT_TRANSITION_RESULT_UNSPECIFIED
}

