func GenerateRefundId() (string, error) {
	sID, err := generateSnowflakeID()
	if err != nil {
		return "", err
	}

	externalOrderId := fmt.Sprintf("%s-r%010d", config.OrderIDPrefix, sID)

	return externalOrderId, nil
}

func generateSnowflakeID() (int64, error) {
	node, err := snowflake.NewNode(1)
	if err != nil {
		return 0, fmt.Errorf("failed to create a new Snowflake node: %w", err)
	}

	return node.Generate().Int64() % maxOrderId, nil
}

func (c *Client) Refund(ctx context.Context, params *dto.RefundParams) (*dto.PaymentReply, error) {
	ctx, span := tracing.Start(ctx, "paymentprocessing:Refund")
	defer span.End()

	span.SetAttributes(
		attribute.String("external_order_id", params.OrderID),
	)

	req := genGRPC.RefundV3Request{
		Options:      nil,
		OrderNumber:  params.OrderID,
		Client:       genGRPC.ClientEnum(params.Client), //nolint:gosec
		RefundNumber: params.RefundID,
		TotalSum:     params.TotalSum,
		CartItems:    nil,
		Services: &genGRPC.Services{
			Delivery:     nil,
			Courier:      nil,
			Subscription: nil,
			ServiceFee:   nil,
			Assembly:     nil,
			DeliveryV2:   nil,
		},
	}

	if params.DeliveryService != nil {
		req.Services.DeliveryV2 = &genGRPC.Delivery{
			Price: &genGRPC.Price{
				Currency: genGRPC.CurrencyEnum_RUB,
				Value:    params.DeliveryService.Price.Value,
			},
			TaxType:  nil,
			Supplier: nil,
		}
	}

	if params.CourierService != nil {
		req.Services.Courier = &genGRPC.Courier{
			Price: &genGRPC.Price{
				Currency: genGRPC.CurrencyEnum_RUB,
				Value:    params.CourierService.Price.Value,
			},
		}
	}

	reply, err := c.client.PMSService.RefundV3(ctx, &req)
	if err != nil {
		switch {
		case genGRPC.IsErr(err, genGRPC.ActionV2Reply_VALIDATION_ERROR):
			return nil, ErrValidationError

		case genGRPC.IsErr(err, genGRPC.ActionV2Reply_OPERATION_NOT_ALLOWED):
			return nil, ErrOperationNotAllowed

		case genGRPC.IsErr(err, genGRPC.ActionV2Reply_PAYMENT_METHOD_NOT_FOUND):
			return nil, ErrPaymentMethodNotFound

		case genGRPC.IsErr(err, genGRPC.ActionV2Reply_PAYMENT_METHOD_NOT_AVAILABLE):
			return nil, ErrPaymentMethodNotAvailable

		case genGRPC.IsErr(err, genGRPC.ActionV2Reply_PAYMENT_NOT_FOUND):
			return nil, ErrPaymentMethodNotFound

		case genGRPC.IsErr(err, genGRPC.ActionV2Reply_CART_NOT_FOUND):
			return nil, ErrPaymentCartNotFound

		default:
			return nil, fmt.Errorf("c.client.PMSService.RefundV3: %w", err)
		}
	}

	return toDTOReply(reply), nil
}

