func (d *Consumer) HandleMessage(
	ctx context.Context,
	msg *paymentGen.PaymentProcessingOrderPaymentEventV2Message,
) error {
	val := msg.Value

	var err error

	switch val.GetOperation() {
	case paymentGen.OrderPaymentEventV2_OPERATION_TYPE__UNSPECIFIED:
	case paymentGen.OrderPaymentEventV2_OPERATION_TYPE__HOLD_AND_DEPOSIT:
	case paymentGen.OrderPaymentEventV2_OPERATION_TYPE__HOLD:
		err = d.controller.handleCreated(ctx, msg)

	case paymentGen.OrderPaymentEventV2_OPERATION_TYPE__DEPOSIT:
		err = d.controller.handleDeposited(ctx, msg)

	case paymentGen.OrderPaymentEventV2_OPERATION_TYPE__CANCEL:
		err = d.controller.handleCanceled(ctx, msg)

	case paymentGen.OrderPaymentEventV2_OPERATION_TYPE__REFUND:
		err = d.controller.handleRefund(ctx, msg)

	default:
		return errors.New("unspecified event")
	}

	if err != nil {
		d.logger.Error("payment error", zap.Error(err))
	}

	return nil
}

