func (c *controller) handleCreated(
	ctx context.Context,
	msg *paymentGen.PaymentProcessingOrderPaymentEventV2Message,
) error {
	event := msg.Value

	orderID := event.GetOrderNumber()
	client := event.GetClient()

	if !strings.HasPrefix(orderID, config.OrderIDPrefix) {
		// не наш заказ
		return nil
	}

	if event.GetOperationStatus() != paymentGen.OrderPaymentEventV2_OPERATION_STATUS__SUCCESSFUL {
		payment, err := c.paymentSvc.GetPaymentByOrderIDAndClient(ctx, orderID, int(client))
		if err != nil {
			return fmt.Errorf("c.paymentSvc.GetPaymentByOrderIDAndClient: %w", err)
		}

		reason := event.GetFailedReason()
		if reason == "" {
			reason = failedPaymentMsg
		}

		if err := cancelClaim(ctx, c.claimSvc, payment.ClaimID, reason); err != nil {
			return fmt.Errorf("cancelClaim: %w", err)
		}

		_, err = c.paymentSvc.UpdatePayment(ctx, &dto.UpdatePaymentParams{
			OrderID: orderID,
			Status:  dto.PaymentFailed,
		})
		if err != nil {
			return fmt.Errorf("c.svc.UpdatePayment: %w", err)
		}

		return fmt.Errorf("failed to hold money: %w", ErrTransitionFailed)
	}

	payment, err := c.paymentSvc.UpdatePayment(ctx, &dto.UpdatePaymentParams{
		OrderID: orderID,
		Status:  dto.PaymentHolded,
	})
	if err != nil {
		return fmt.Errorf("c.svc.UpdatePayment: %w", err)
	}

	err = c.claimSvc.AcceptClaim(ctx, payment.ClaimID)
	if err != nil {
		return fmt.Errorf("c.claimSvc.AcceptClaim: %w", err)
	}

	return nil
}

