func toClaimPaymentDomainModel(c *queries.Claim, p *queries.Claimpayment) (claim.Claim, error) {
	var deletedAt *time.Time
	if c.DeletedAt.Valid {
		deletedAt = &c.DeletedAt.Time
	}

	var state claim.State

	err := json.Unmarshal(c.State, &state)
	if err != nil {
		return claim.Claim{}, fmt.Errorf("json.Unmarhsal: %w", err)
	}

	out := claim.Claim{
		ClaimID:         c.ClaimID,
		Tariff:          claim.Tariff(c.Tariff),
		Email:           c.Email,
		UserID:          c.UserID,
		ExternalOrderID: c.ExternalOrderID,
		State:           state,
		Payment:         nil,
		CreatedAt:       c.CreatedAt.Time,
		UpdatedAt:       c.UpdatedAt.Time,
		DeletedAt:       deletedAt,
	}

	if p.CreatedAt.Valid {
		out.Payment = &domain.Payment{
			PaymentID:       int(*p.PaymentID),
			ClaimID:         c.ClaimID,
			OrderID:         c.ExternalOrderID,
			RefundID:        p.RefundID,
			Status:          string(p.Status.PaymentStateEnum),
			PaymentMethodID: *p.PaymentMethodID,
			Client:          int(*p.Client),
			TotalCost:       *p.TotalCost,
			DeliveryCost:    *p.DeliveryCost,
			CourierCost:     *p.CourierCost,
			FinalCost:       *p.FinalCost,
			CreatedAt:       p.CreatedAt.Time,
			UpdatedAt:       p.UpdatedAt.Time,
		}
	}

	return out, nil
}

