func (c *Client) CancelClaim(
	ctx context.Context,
	claim *domainClaim.Claim,
	cancelReason *dto.CancelByPartnerReason,
) error {
	ctx, span := tracing.Start(ctx, "lastmileoms:CancelClaim")
	defer span.End()

	span.SetAttributes(
		attribute.Stringer("claim_id", claim.ClaimID),
	)

	partnerID := c.PartnerIDForTariff(dto.Tariff(claim.Tariff))

	log := c.logger.With(
		zap.String("http_client", "lm_oms"),
		zap.String("method", "cancel_claim"),
		zap.String("claim_id", claim.ClaimID.String()),
		zap.String("partner_id", partnerID),
	)

	var cancelByPartnerReason *lmHTTP.CancelByPartnerReason
	if cancelReason != nil {
		cancelByPartnerReason = &lmHTTP.CancelByPartnerReason{
			Code:    lmHTTP.CancelByPartnerReasonCode(cancelReason.Code),
			Message: cancelReason.Message,
		}
	}

	resp, err := c.client.CancelClaimWithResponse(
		ctx,
		&lmHTTP.CancelClaimParams{
			XPartnerID: partnerID,
		},
		lmHTTP.RequestCancelClaim{
			CancelReason: cancelByPartnerReason,
			ClaimId:      claim.ClaimID,
		},
	)
	if err != nil {
		return fmt.Errorf("c.client.CancelClaim: %w", err)
	}

	switch resp.StatusCode() {
	case http.StatusOK:
		return nil

	default:
		log.Error(
			"unhandled status code",
			zap.Int("status_code", resp.StatusCode()),
		)

		return fmt.Errorf("unhandled status code: %d", resp.StatusCode())
	}
}

