func (c *Client) AcceptClaim(
	ctx context.Context,
	claim *domainClaim.Claim,
) error {
	ctx, span := tracing.Start(ctx, "lastmileoms:AcceptClaim")
	defer span.End()

	span.SetAttributes(
		attribute.Stringer("claim_id", claim.ClaimID),
	)

	partnerID := c.PartnerIDForTariff(dto.Tariff(claim.Tariff))
	log := c.logger.With(
		zap.String("http_client", "lm_oms"),
		zap.String("method", "accept_claim"),
		zap.String("parnter_id", partnerID),
		zap.String("claim_id", claim.ClaimID.String()),
	)

	resp, err := c.client.AcceptClaimWithResponse(
		ctx,
		&lmHTTP.AcceptClaimParams{
			XPartnerID: partnerID,
		},
		lmHTTP.RequestAcceptClaim{
			ClaimId: claim.ClaimID,
		},
	)
	if err != nil {
		return fmt.Errorf("c.client.CreateClaim: %w", err)
	}

	switch resp.StatusCode() {
	case http.StatusOK:
		return nil

	case http.StatusBadRequest:
		log.Error(
			"response code 400",
			zap.Any("details", helpers.Deref(resp.JSON400.Details)),
		)

		return infra.ErrBadRequest

	default:
		log.Error(
			"unhandled status code",
			zap.Int("status_code", resp.StatusCode()),
		)

		return fmt.Errorf("unhandled status code: %d", resp.StatusCode())
	}
}

