func (c *controller) handleDeposited(
	ctx context.Context,
	msg *paymentGen.PaymentProcessingOrderPaymentEventV2Message,
) error {
	event := msg.Value

	orderID := event.GetOrderNumber()

	if !strings.HasPrefix(orderID, config.OrderIDPrefix) {
		// не наш заказ
		return nil
	}

	if event.GetOperationStatus() != paymentGen.OrderPaymentEventV2_OPERATION_STATUS__SUCCESSFUL {
		return fmt.Errorf("failed to deposit money: %w", ErrTransitionFailed)
	}

	params := &dto.UpdatePaymentParams{
		OrderID: orderID,
		Status:  dto.PaymentDeposited,
	}

	_, err := c.paymentSvc.UpdatePayment(ctx, params)
	if err != nil {
		return fmt.Errorf("c.svc.UpdatePayment: %w", err)
	}

	claim, err := c.claimSvc.GetClaimByExternalOrderID(ctx, orderID)
	if err != nil {
		return fmt.Errorf("c.claimSvc.GetUserClaimByExternalOrderID: %w", err)
	}

	if claim.State.Status == domainClaim.StatusCancelledWithPayment {
		_, err = c.paymentSvc.RefundDeliveryService(ctx, claim.ClaimID)
		if err != nil {
			return fmt.Errorf("c.paymentSvc.RefundDeliveryService: %w", err)
		}
	}

	return nil
}

func (x *OrderPaymentEventV2) GetOrderNumber() string {
	if x != nil {
		return x.OrderNumber
	}
	return ""
}

func (x *OrderPaymentEventV2) GetOperationStatus() OrderPaymentEventV2_OperationStatusV2 {
	if x != nil {
		return x.OperationStatus
	}
	return OrderPaymentEventV2_OPERATION_STATUS__UNSPECIFIED
}

func (s *Service) UpdatePayment(ctx context.Context, params *dto.UpdatePaymentParams) (*domain.Payment, error) {
	ctx, span := tracing.Start(ctx, "payment:UpdatePayment")
	defer span.End()

	payment, err := s.paymentRepo.GetPaymentByOrderIDAndClient(ctx, &dto.GetDBPaymentParams{
		OrderID: params.OrderID,
		Client:  s.paymentProcessor.ClientID(),
	})
	if err != nil {
		s.logger.Error(
			"failed to get payment for by external order id",
			zap.String("external_order_id", params.OrderID),
			zap.Error(err),
		)

		return nil, fmt.Errorf("s.paymentRepo.GetPaymentByOrderIDAndClient: %w", err)
	}

	payment.Status = string(params.Status)

	switch params.Status { //nolint: exhaustive
	case dto.PaymentDeposited:
		payment.FinalCost = payment.TotalCost
	case dto.PaymentRefunded:
		payment.FinalCost = payment.CourierCost
	case dto.PaymentCanceled:
		payment.FinalCost = 0
	}

	if _, err := s.paymentRepo.Save(ctx, payment); err != nil {
		s.logger.Error(
			"failed to save payment",
			zap.String("claim_id", payment.ClaimID.String()),
			zap.String("external_order_id", payment.OrderID),
			zap.Error(err),
		)

		return nil, fmt.Errorf("s.paymentRepo.Save: %w", err)
	}

	s.logger.Info(
		"payment updated",
		zap.String("claim_id", payment.ClaimID.String()),
		zap.String("external_order_id", payment.OrderID),
		zap.Any("payment_status", payment.Status),
	)

	return payment, nil
}

