func (h *Handlers) LastMileC2CServiceCreateTrackingLink(
	ctx context.Context, req *servergrpc.CreateTrackingLinkRequest,
) (*servergrpc.CreateTrackingLinkReply, error) {
	var claimID uuid.UUID

	err := claimID.Scan(req.ClaimId)
	if err != nil {
		return nil, servergrpc.GRPCCustomError(
			codes.InvalidArgument,
			servergrpc.CreateTrackingLinkReply_VALIDATION_ERROR,
			fmt.Errorf("failed to parse claim ID: %w", err),
		)
	}

	partnerID, err := uuid.Parse(req.PartnerId)
	if err != nil {
		return nil, servergrpc.GRPCCustomError(
			codes.InvalidArgument,
			servergrpc.CreateTrackingLinkReply_VALIDATION_ERROR,
			fmt.Errorf("failed to parse partner ID: %w", err),
		)
	}

	link, err := h.Service.TrackingLinkService.CreateLink(
		ctx,
		dto.CreateTrackingLinkRequest{
			ClaimID:     claimID,
			Source:      dto.ToDomain(req.Source),
			UserPhone:   req.UserPhone,
			LinkTTL:     time.Duration(req.LinkTtl),
			PartnerID:   partnerID,
			DisplayName: req.PartnerDisplayName,
		},
	)
	if err != nil {
		return nil, servergrpc.GRPCCustomError(
			codes.Internal,
			servergrpc.CreateTrackingLinkReply_UNSPECIFIED,
			err,
		)
	}

	return &servergrpc.CreateTrackingLinkReply{
		Link: link,
	}, nil
}

