func (s *Service) CreateLink(
	ctx context.Context, request dto.CreateTrackingLinkRequest,
) (string, error) {
	now := time.Now()

	pgRequest := dto.CreateTrackingLinkParams{
		ClaimID:     request.ClaimID,
		Source:      request.Source,
		UserPhone:   request.UserPhone,
		CreatedAt:   now,
		ExpiresAt:   now.Add(request.LinkTTL),
		PartnerID:   request.PartnerID,
		DisplayName: request.DisplayName,
	}

	baseURL := strings.TrimRight(s.baseURL, "/")
	link := fmt.Sprintf(
		"%s/tracking/%s",
		baseURL,
		helpers.ShortID(request.ClaimID.String()),
	)

	if err := s.repository.TrackingLink.Create(ctx, pgRequest); err != nil {
		if errors.Is(err, repo.ErrTrackingLinkAlreadyExists) {
			return link, nil
		}

		return "", fmt.Errorf("repository.TrackingLink.Create: %w", err)
	}

	s.tryToAssignMagnitID(ctx, request.UserPhone, request.ClaimID.String())

	return link, nil
}

func ShortID(id string) string {
	s := strings.ReplaceAll(id, "-", "")
	if len(s) >= shortenLen {
		return s[len(s)-shortenLen:]
	}

	return s
}

func (r *Repository) Create(ctx context.Context, params dto.CreateTrackingLinkParams) error {
	p := queries.CreateTrackingLinkParams{
		ClaimID:            params.ClaimID,
		Source:             mapPgSource(params.Source),
		CreatedAt:          transformers.TimeToPg(params.CreatedAt),
		ExpiresAt:          transformers.TimeToPg(params.ExpiresAt),
		UserPhone:          &params.UserPhone,
		PartnerID:          params.PartnerID,
		PartnerDisplayName: params.DisplayName,
		ShortID:            helpers.ShortID(params.ClaimID.String()),
	}
	if err := r.master.CreateTrackingLink(ctx, p); err != nil {
		var pgErr *pgconn.PgError
		if errors.As(err, &pgErr) && pgErr.Code == "23505" {
			return ErrTrackingLinkAlreadyExists
		}

		return fmt.Errorf("r.master.CreateTrackingLink: %w", err)
	}

	return nil
}

