func (s *Service) tryToAssignMagnitID(ctx context.Context, rawPhone string, claimID string) {
	log := s.logger.With(
		zap.String("method", "tryToAssignMagnitID"),
		zap.String("claim_id", claimID),
	)

	phone := strings.Replace(rawPhone, "+", "", 1)

	pPhones, magnitIDs, err := s.personalDataServiceCl.GetListProfile(ctx, []string{phone})
	if err != nil {
		log.Warn("failed to get magnitID", zap.Error(err))

		return
	}

	if len(pPhones) == 0 {
		log.Info("no magnitID returned")

		return
	}

	if err := s.repository.TrackingLink.SetMagnitIDByUserPhone(ctx, pPhones, magnitIDs); err != nil {
		log.Warn("failed to set magnitID", zap.Error(err))

		return
	}

	log.Info("successfully assigned")
}

func (c *Client) GetListProfile(ctx context.Context, phones []string) ([]string, []string, error) {
	if len(phones) == 0 {
		return nil, nil, nil
	}

	resp, err := c.client.ProfileService.GetListProfile(ctx, &grpc.GetListProfileRequest{ //nolint:exhaustruct
		Phones: phones,
	})
	if err != nil {
		return nil, nil, fmt.Errorf("get list profile: %w", err)
	}

	profiles := resp.GetProfiles()

	pPhones := make([]string, 0, len(profiles))
	ids := make([]string, 0, len(profiles))

	for _, p := range profiles {
		// добавляем '+', т.к в ответе от сервиса профилей его нет
		pPhones = append(pPhones, "+"+p.GetPhone())
		ids = append(ids, p.GetUserId())
	}

	return pPhones, ids, nil
}

