	cOpts := append([]grpc.CallOption{grpc.StaticMethod()}, opts...)
	out := new(GetListProfileReply)
	err := c.cc.Invoke(ctx, ProfileService_GetListProfile_FullMethodName, in, out, cOpts...)
	if err != nil {
