func (r *Repository) SetMagnitIDByUserPhone(ctx context.Context, profilePhone []string, magnitID []string) error {
	if len(profilePhone) == 0 || len(magnitID) == 0 {
		return nil
	}

	if len(profilePhone) != len(magnitID) {
		return ErrIDsAndMagnitIDsLengthMismatch
	}

	err := r.master.SetMagnitIDByID(ctx, queries.SetMagnitIDByIDParams{
		MagnitID:  magnitID,
		UserPhone: profilePhone,
	})
	if err != nil {
		return fmt.Errorf("master.SetMagnitIDByUserPhone: %w", err)
	}

	return nil
}

